script:
frappe.ui.form.on('Lead', {
	refresh: function(frm) {
        setTimeout(() => {
            frm.remove_custom_button('Opportunity', 'Create'); 
            frm.remove_custom_button('Prospect', 'Create');
            }, 1000);
   },
   party_name: function(frm) {
        // to fetch sales team table from customer master
        if (frm.doc.opportunity_from == "Customer" && frm.doc.party_name) {
            frm.clear_table('custom_sales_team');
            frappe.model.with_doc('Customer', frm.doc.party_name, function () {
                let source_doc = frappe.model.get_doc('Customer', frm.doc.party_name);
                $.each(source_doc.sales_team, function (index, source_row) {
                    frm.add_child('custom_sales_team').sales_person = source_row.sales_person; // this table has only one column. You might want to fill more columns.
                    frm.refresh_field('custom_sales_team');
                });
            });
        }
    }
});

frappe.ui.form.on('Appointment Letter', {
    refresh: frm => {
        let fld = frm.fields_dict.custom_offer_terms_salary;
        if (!fld) return;
        fld.$wrapper.prev('.offer-btn').remove();
        $(`<div class="offer-btn" style="margin-bottom:8px;">
             <button class="btn btn-primary btn-xs">Fetch Offer Terms</button>
           </div>`).insertBefore(fld.$wrapper)
           .find('button').on('click', () => fetch_terms(frm));
    },
    custom_job_offer: frm => fetch_terms(frm)
});

function fetch_terms(frm) {
    if (!frm.doc.custom_job_offer) return frm.set_value("custom_offer_terms_salary", "");
    frappe.call({
        method: "frappe.client.get",
        args: { doctype: "Job Offer", name: frm.doc.custom_job_offer },
        callback: r => {
            let t = r.message?.offer_terms || [];
            let rows = t.map((row, i) =>
                `<tr><td align="center">${i+1}</td><td>${row.value||""}</td>
                 <td align="right">${fmt(row.custom_monthly)}</td><td align="right">${fmt(row.custom_yearly)}</td></tr>`
            ).join("");
            let net = t.find(x => x.value=="Net Payable"),
                gross = t.find(x => x.value=="Gross Salary")

            frm.set_value("custom_offer_terms_salary", `
                <table border="1" cellpadding="5" cellspacing="0"
                       style="width:100%;border-collapse:collapse;font-size:12px;margin-bottom:10px;">
                    <tr style="background:#f0f0f0;font-weight:bold;text-align:center;">
                        <td>No.</td><td>Offer Term</td><td style="width:15%;">Monthly</td><td style="width:15%;">Yearly</td>
                    </tr>${rows}
                </table>
                <div style="font-weight:bold;font-size:13px;line-height:1.6;">
                    Net Take Home Salary: ${fmt(net?.custom_monthly)}<br>
                    Gross Salary: ${fmt(gross?.custom_monthly)}<br>

                </div>`);
        }
    });
}

const fmt = n => (n||0).toLocaleString("en-IN",{maximumFractionDigits:0});

frappe.ui.form.on('Appointment Letter', {
    validate: render_placeholders,
    custom_al_template: render_placeholders
});

function render_placeholders(frm) {
    if (!frm.doc.custom_al_template) return;

    frappe.db.get_value("AL Template", frm.doc.custom_al_template, "description").then(r => {
        let template = r.message?.description || "";
        frm.set_value("custom_description", template.replace(/{{\s*([\w_]+)\s*}}/g, (_, f) => {
            let val = frm.doc[f];
            let df = frappe.meta.get_docfield(frm.doctype, f);
            return df?.fieldtype === "Date" && val ? frappe.datetime.str_to_user(val) : (val || "");
        }));
    });
}



frappe.ui.form.on('Appointment Letter', {
    appointment_letter_template: function(frm) {
        if (frm.doc.appointment_letter_template) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Appointment Letter Template',
                    name: frm.doc.appointment_letter_template
                },
                callback: function(response) {
                    if (response.message) {
                        frm.set_value('terms', response.message.terms);
                    }
                }
            });
        }
    }
});



frappe.ui.form.on('Appointment Letter', {
    validate: render_role_responsibilities,
    custom_role_responsibilities_temples: render_role_responsibilities
});

function render_role_responsibilities(frm) {
    if (!frm.doc.custom_role_responsibilities_temples) return;

    frappe.db.get_value("Role Responsibilities", frm.doc.custom_role_responsibilities_temples, "role_responsibilities").then(r => {
        let template = r.message?.role_responsibilities || "";
        frm.set_value("custom_role_responsibilities_description", template.replace(/{{\s*([\w_]+)\s*}}/g, (_, f) => {
            let val = frm.doc[f];
            let df = frappe.meta.get_docfield(frm.doctype, f);
            return df?.fieldtype === "Date" && val ? frappe.datetime.str_to_user(val) : (val || "");
        }));
    });
}

frappe.ui.form.on('Appointment Letter', {
    validate: function(frm) {
        calculate_terms(frm);
    },
    custom_base: function(frm) {
        calculate_terms(frm);
    }
});

frappe.ui.form.on('Appointment Letter Terms', {
    custom_monthly: function(frm) {
        calculate_terms(frm);
    },
    custom_formula: function(frm) {
        calculate_terms(frm);
    }
});

function calculate_terms(frm) {
    let values = {};

    // Map parent base values
    values["Base"] = flt(frm.doc.custom_base);
    values["custom_base"] = flt(frm.doc.custom_base);

    // Step 1: Store direct values first
    frm.doc.terms.forEach(row => {
        if (row.custom_abbreviation && (!row.custom_formula || row.custom_formula.trim() === "")) {
            values[row.custom_abbreviation] = flt(row.custom_monthly);
        }
    });

    // Step 2: Compute formulas (Excel-like)
    frm.doc.terms.forEach(row => {
        if (row.custom_formula) {
            let expr = row.custom_formula;

            // Replace % with *0.01 (Excel-style 10% → 0.10)
            expr = expr.replace(/([0-9]+)%/g, function(match, p1) {
                return String(parseFloat(p1) / 100);
            });

            // Replace abbreviations (BA, HRA, etc.)
            Object.keys(values).forEach(abbr => {
                let regex = new RegExp("\\b" + abbr + "\\b", "g");
                expr = expr.replace(regex, values[abbr]);
            });

            // Evaluate safely
            let result = safeEval(expr);
            row.custom_monthly = flt(result);
            values[row.custom_abbreviation] = row.custom_monthly;
        }
    });

    // Step 3: Compute yearly as 12x
    frm.doc.terms.forEach(row => {
        row.custom_yearly = flt(row.custom_monthly) * 12;
    });

    frm.refresh_field("terms");
}

function safeEval(expr) {
    // Only numbers + basic math allowed
    if (/^[0-9+\-*/ ().]+$/.test(expr)) {
        try {
            return Function('"use strict";return (' + expr + ')')();
        } catch (e) {
            return 0;
        }
    }
    return 0;
}

frappe.ui.form.on('Job Applicant', {
  async refresh(frm) {
    hard_hide_create_for_nonaccepted(frm);   // hide by default unless accepted
    build_create_menu_if_accepted(frm);      // add items only if accepted
    scrub_unwanted(frm);                     // remove Job Offer/others
    late_passes(frm);                        // re-apply after late renders
    observe_toolbar_mutations(frm);          // keep it enforced across rerenders
  },

  onload_post_render(frm) {
    hard_hide_create_for_nonaccepted(frm);
    late_passes(frm);
  },

  // When status changes on the form, rebuild visibility immediately
  status(frm) {
    // Clear anything previously added under Create
    ['Employee', 'Appointment Letter', 'Job Offer', 'Interview', 'Employee Onboarding']
      .forEach(lbl => frm.remove_custom_button(__(lbl), __('Create')));

    hard_hide_create_for_nonaccepted(frm);
    build_create_menu_if_accepted(frm);
    scrub_unwanted(frm);
    late_passes(frm);
  }
});

/* ---------------- Core logic ---------------- */

function is_accepted(frm) {
  return (frm.doc.status || '').toLowerCase() === 'accepted';
}

function get_create_group(frm) {
  return $(frm.wrapper).find('.custom-actions .dropdown')
    .filter(function () {
      const txt = $(this).find('.dropdown-toggle').text().trim();
      return /^Create$/i.test(txt);
    });
}

function hard_hide_create_for_nonaccepted(frm) {
  const $grp = get_create_group(frm);
  if (!$grp.length) return;
  if (!is_accepted(frm)) {
    $grp.removeClass('open show');
    $grp.find('.dropdown-menu').removeClass('show');
    $grp.hide();
  } else {
    $grp.show();
  }
}

function build_create_menu_if_accepted(frm) {
  if (!is_accepted(frm)) return;

  // ensure Create group is visible
  const $grp = get_create_group(frm);
  if ($grp.length) $grp.show();

  // add only your two allowed actions
  frm.add_custom_button(__('Employee'), async () => {
    await create_employee_from_applicant(frm);
  }, __('Create'));

  frm.add_custom_button(__('Appointment Letter'), () => {
    create_appointment_letter_from_applicant(frm);
  }, __('Create'));
}

function scrub_unwanted(frm) {
  // Remove unwanted items from Create (if they ever appear)
  ['Job Offer', 'Interview', 'Employee Onboarding'].forEach(lbl => {
    frm.remove_custom_button(__(lbl), __('Create'));
  });

  // Clean dashboard connections (optional but keeps UI tidy)
  if (frm.dashboard?.wrapper) {
    const container = frm.dashboard.wrapper.find('.form-links').get(0);
    if (container) {
      ['Job Offer', 'Interview', 'Employee Onboarding'].forEach(doctype => {
        container.querySelectorAll(`.row-connection[data-doctype="${doctype}"]`)
          .forEach(el => {
            const next = el.nextElementSibling;
            if (next && next.classList.contains('btn')) next.remove();
            el.remove();
          });
      });
    }
  }
}

function late_passes(frm) {
  // After late renders or route switches, re-enforce
  setTimeout(() => {
    scrub_unwanted(frm);
    hard_hide_create_for_nonaccepted(frm);
  }, 250);

  setTimeout(() => {
    scrub_unwanted(frm);
    hard_hide_create_for_nonaccepted(frm);
  }, 600);
}

let __observerAttached = false;
function observe_toolbar_mutations(frm) {
  if (__observerAttached) return;
  const target = frm.wrapper?.get(0);
  if (!target) return;

  const obs = new MutationObserver(() => {
    // Any time the toolbar reflows/rebuilds, re-apply the rule
    hard_hide_create_for_nonaccepted(frm);
    scrub_unwanted(frm);
  });

  obs.observe(target, { childList: true, subtree: true });
  __observerAttached = true;
}

/* ---------------- Your existing helpers ---------------- */

async function create_employee_from_applicant(frm) {
  await frappe.model.with_doctype('Employee');
  const emp = frappe.model.get_new_doc('Employee');

  const parts = (frm.doc.applicant_name || '').trim().split(/\s+/);
  emp.first_name    = parts[0] || '';
  emp.last_name     = parts.slice(1).join(' ');
  emp.employee_name = frm.doc.applicant_name;

  emp.gender          = frm.doc.gender;
  emp.date_of_birth   = frm.doc.date_of_birth;
  emp.date_of_joining = frappe.datetime.get_today();

  const mapMarital = v => {
    const t = (v || '').toLowerCase();
    if (['unmarried','single','not married'].includes(t)) return 'Single';
    if (t === 'married') return 'Married';
    if (t === 'divorced') return 'Divorced';
    if (t === 'widowed')  return 'Widowed';
    if (t === 'separated') return 'Separated';
    return '';
  };
  emp.marital_status = mapMarital(frm.doc.marital_status);

  emp.personal_email = frm.doc.email_id || frm.doc.email_address;
  emp.cell_number    = frm.doc.phone_number;
  emp.job_applicant  = frm.doc.name;

  (frm.doc.education || []).forEach(r => {
    const c = frappe.model.add_child(emp, 'Employee Education', 'education');
    c.school_univ     = r.school_univ || '';
    c.qualification   = r.qualification || '';
    c.level           = r.level || '';
    c.year_of_passing = r.year_of_passing || '';
    if (r.class_per) c.class_per = r.class_per;
    if (r.maj_opt_subj) c.maj_opt_subj = r.maj_opt_subj;
  });

  (frm.doc.external_work_history || []).forEach(r => {
    const c = frappe.model.add_child(emp, 'Employee External Work History', 'external_work_history');
    c.company_name = r.company_name || r.company || '';
    c.designation  = r.designation || '';
    c.salary       = r.salary || '';
    c.address      = r.address || '';
  });

  if (frm.doc.job_opening) {
    try {
      const jo = await frappe.db.get_doc('Job Opening', frm.doc.job_opening);
      emp.company         = jo.company || frappe.defaults.get_user_default('Company');
      emp.designation     = emp.designation || jo.designation;
      emp.branch          = jo.branch || '';
      emp.department      = jo.department || '';
      emp.grade           = jo.grade || '';
      emp.employment_type = jo.employment_type || '';
      emp.reports_to      = jo.reports_to || '';
      if (emp.company) {
        const { message } = await frappe.db.get_value('Company', emp.company, 'default_holiday_list');
        emp.holiday_list = jo.holiday_list || message?.default_holiday_list || '';
      }
      emp.default_shift    = jo.default_shift || '';
      emp.expense_approver = jo.expense_approver || '';
      emp.leave_approver   = jo.leave_approver || '';
    } catch {}
  } else {
    emp.company = frappe.defaults.get_user_default('Company') || '';
  }

  frappe.set_route('Form', emp.doctype, emp.name);
}

function create_appointment_letter_from_applicant(frm) {
  frappe.route_options = {
    job_applicant: frm.doc.name,
    applicant_name: frm.doc.applicant_name,
    email_id: frm.doc.email_id || frm.doc.email_address,
    phone_number: frm.doc.phone_number,
    date_of_birth: frm.doc.date_of_birth,
    gender: frm.doc.gender
  };
  frappe.new_doc('Appointment Letter');
}

// Doctype: Employee  (Client Script)
frappe.ui.form.on('Employee', {
  onload: copy_family_from_applicant,
  job_applicant: copy_family_from_applicant
});

async function copy_family_from_applicant(frm) {
  try {
    if (!frm.doc.job_applicant) return;

    // don't overwrite if target already has rows
    if ((frm.doc.custom_family_info || []).length) return;

    const applicant = await frappe.db.get_doc('Job Applicant', frm.doc.job_applicant);
    const src_rows = applicant.custom_family_info || [];
    if (!src_rows.length) return;

    const child_doctype = frm.fields_dict.custom_family_info.grid.doctype;
    const child_meta = frappe.get_meta(child_doctype);
    const allowed = new Set(child_meta.fields.map(f => f.fieldname));
    const skip = new Set([
      'name','doctype','idx','owner','creation','modified','modified_by',
      'docstatus','parent','parenttype','parentfield'
    ]);

    frm.clear_table('custom_family_info');
    src_rows.forEach(r => {
      const row = frm.add_child('custom_family_info');
      Object.keys(r).forEach(k => {
        if (!skip.has(k) && allowed.has(k)) row[k] = r[k];
      });
    });

    frm.refresh_field('custom_family_info');
  } catch (e) {
    console.error('Family copy failed:', e);
    frappe.msgprint(__('Could not copy Family Details from Job Applicant.'));
  }
}

// Leave Application — Earned Leaves shown + draft hint
const TARGET_LEAVE_TYPE = 'Earned Leaves';
const PRESENT_STATUSES  = ['Present', 'Work From Home', 'On Duty'];

function num(x){ return x==null?0:(typeof x==='number'?x:(parseFloat(x)||0)); }
function iso(d){ if(!d) return null; return frappe.datetime.obj_to_str(d); }
function toDate(val){ if (!val) return null; if (val instanceof Date) return val; try { return frappe.datetime.str_to_obj(val); } catch(e){ 
  try { const dd = new Date(val); return isNaN(dd.getTime())?null:dd; } catch(_) { return null; }
} }
function pickAsOfDate(doc){ return toDate(doc.posting_date) || toDate(doc.from_date) || toDate(frappe.datetime.get_today()); }
function roundHalf(x){ const v = Math.floor(x), d = x - v; if (d < 0.25) return v; if (d < 0.75) return v + 0.5; return v + 1; }

function customEntitlementRound(x){
  if (x == null) return 0; const n = Number(x); if (!isFinite(n)) return 0;
  const sign = n < 0 ? -1 : 1; const abs = Math.abs(n); const intPart = Math.floor(abs);
  const dec = +(abs - intPart).toFixed(3);
  if (dec < 0.45) return sign * intPart;
  if (dec < 0.55) return sign * (intPart + 0.5);
  return sign * (intPart + 1);
}

async function fcall(method, args){ return new Promise((res,rej)=>{ frappe.call({ method, args, callback:r=>res(r && r.message), error:rej }); }); }
async function gv(doctype, fieldname, filters){ return fcall('frappe.client.get_value', { doctype, fieldname, filters }); }
async function gc(doctype, filters){ return fcall('frappe.client.get_count', { doctype, filters }); }
async function gl(doctype, filters, fields=['name'], limit=5000){ return fcall('frappe.client.get_list', { doctype, fields, filters, limit_page_length: limit }); }
async function get_doc(doctype, name){ return fcall('frappe.client.get', { doctype, name }); }

async function presentFromAttendance(employee, startISO, endISO){
  let total = 0;
  for (const st of PRESENT_STATUSES){
    total += await gc('Attendance', { employee, status: st, attendance_date: ['between', [startISO, endISO]], docstatus: 1 }) || 0;
    total += await gc('Attendance', { employee, status: st, attendance_date: ['between', [startISO, endISO]], docstatus: 0 }) || 0;
  }
  return total;
}
async function presentFromCheckins(employee, startObj, endObj){
  const startTS = iso(startObj) + ' 00:00:00';
  const endTS   = iso(endObj)   + ' 23:59:59';
  const rows = await gl('Employee Checkin', { employee, time: ['between', [startTS, endTS]] }, ['time'], 10000) || [];
  const days = new Set(); rows.forEach(r => { if (r.time) days.add(String(r.time).slice(0,10)); });
  return days.size;
}

function pickNumericFromRecord(rec){
  const candidates = ['new_leaves_allocated','total_leaves_allocated','allocated_leaves','leaves_allocated'];
  for (const k of candidates){ if (rec && rec.hasOwnProperty(k) && rec[k] != null && !isNaN(Number(rec[k]))) return Number(rec[k]); }
  for (const k in rec){ if (rec[k] != null && !isNaN(Number(rec[k]))) return Number(rec[k]); }
  return 0;
}

async function getAllocatedSumForYear(employee, leave_type, year){
  const yStart = toDate(`${year}-01-01`); const yEnd = toDate(`${year}-12-31`);
  let rows = [];
  try {
    rows = await gl('Leave Allocation', { employee, leave_type, from_date: ['>=', iso(yStart)], to_date: ['<=', iso(yEnd)] }, ['name','docstatus'], 1000) || [];
  } catch (e) { console.error('getAllocatedSumForYear.get_list error', e); return { sum:0, any_submitted:false, draft_only:false }; }

  let sum = 0;
  let any_submitted = false;
  let any_draft = false;

  for (const r of rows){
    try {
      const rec = await get_doc('Leave Allocation', r.name);
      const val = pickNumericFromRecord(rec || {});
      sum += val;
      if (rec && rec.docstatus === 1) any_submitted = true;
      if (rec && rec.docstatus === 0) any_draft = true;
    } catch (err) {
      console.warn(`Failed to fetch allocation ${r.name}`, err);
    }
  }

  return { sum, any_submitted, draft_only: (any_draft && !any_submitted) };
}

async function computeSnapshot(doc){
  if (!doc.employee) return null;
  const posting = pickAsOfDate(doc);
  const emp_fields = await fcall('frappe.client.get_value', { doctype: 'Employee', fieldname: ['date_of_joining','department'], filters: { name: doc.employee } });
  if (!emp_fields || !emp_fields.date_of_joining) return null;
  const doj = toDate(emp_fields.date_of_joining);
  const dojISO = iso(doj), postingISO = iso(posting);

  // present since DOJ (docstatus 0 & 1)
  let present_since_join = (await presentFromAttendance(doc.employee, dojISO, postingISO)) || (await presentFromCheckins(doc.employee, doj, posting));
  const eligible = present_since_join >= 180 ? 1 : 0;

  const postingYear = (pickAsOfDate(doc)).getFullYear();
  const prevYear = postingYear - 1;
  let prev_year_present = 0; let entitled_raw = 0.0;
  if (eligible) {
    const prevStart = toDate(`${prevYear}-01-01`), prevEnd = toDate(`${prevYear}-12-31`);
    prev_year_present = (await presentFromAttendance(doc.employee, iso(prevStart), iso(prevEnd))) || (await presentFromCheckins(doc.employee, prevStart, prevEnd));
    entitled_raw = prev_year_present / 20.0;
  }
  const computed_entitled = customEntitlementRound(entitled_raw);

  const alloc = await getAllocatedSumForYear(doc.employee, TARGET_LEAVE_TYPE, postingYear);
  const allocated_sum = num(alloc.sum || 0);
  const allocated_overrode = allocated_sum > 0;
  const entitled = allocated_overrode ? allocated_sum : computed_entitled;

  const yStart = toDate(`${postingYear}-01-01`), yEnd = toDate(`${postingYear}-12-31`);
  const takenRows = await gl('Leave Application', { employee: doc.employee, leave_type: TARGET_LEAVE_TYPE, status: 'Approved', docstatus: 1, from_date: ['>=', iso(yStart)], to_date: ['<=', iso(yEnd)] }, ['total_leave_days'], 1000) || [];
  const pendingRows = await gl('Leave Application', { employee: doc.employee, leave_type: TARGET_LEAVE_TYPE, status: 'Open', docstatus: 0, from_date: ['>=', iso(yStart)], to_date: ['<=', iso(yEnd)] }, ['total_leave_days'], 1000) || [];
  const taken = takenRows.reduce((s,x)=>s+num(x.total_leave_days),0);
  const pending = pendingRows.reduce((s,x)=>s+num(x.total_leave_days),0);

  return {
    eligible,
    computed_entitled,
    allocated_sum,
    allocated_overrode,
    entitled,
    taken, pending,
    remaining: roundHalf(entitled - taken >= 0 ? (entitled - taken) : 0),
    available: roundHalf((entitled - taken) - pending >= 0 ? ((entitled - taken) - pending) : 0),
    department: emp_fields.department || '',
    allocation_has_submitted: !!alloc.any_submitted,
    allocation_draft_only: !!alloc.draft_only
  };
}

function getAllocatedSection(){
  const $sec = $('.form-dashboard-section').filter(function(){ return $(this).find('.section-head:contains("Allocated Leaves")').length > 0; }).first();
  return $sec.length ? $sec : null;
}
function ensureStandardTable($sec){
  let $table = $sec.find('table').first();
  if (!$table.length){
    const html = `
      <table class="table table-bordered">
        <thead><tr>
          <th>Leave Type</th><th>Total Allocated Leaves</th><th>Expired Leaves</th><th>Used Leaves</th><th>Leaves Pending Approval</th><th>Available Leaves</th>
        </tr></thead><tbody></tbody></table>`;
    let $body = $sec.find('.section-body').first();
    if (!$body.length) $body = $('<div class="section-body"></div>').appendTo($sec);
    $body.children().each(function(){ if ($(this).text().trim().match(/^No leaves have been allocated/i)) $(this).hide(); });
    $body.html(html);
    $table = $body.find('table').first();
  }
  return $table;
}
function escapeHtml(s){ return frappe.utils && frappe.utils.escape_html ? frappe.utils.escape_html(s) : String(s||''); }

function updateAllocatedTable(snapshot, yearNote){
  const $sec = getAllocatedSection();
  if (!$sec) return;
  const $table = ensureStandardTable($sec);
  const $tbody = $table.find('tbody');
  $tbody.empty();
  if (!snapshot){
    $tbody.append(`<tr><td>${escapeHtml(TARGET_LEAVE_TYPE)}</td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td></tr>`);
    return;
  }

  let deptHtml = snapshot.department ? `<div style="color:#666;margin-top:4px;font-size:0.9em">${escapeHtml(snapshot.department)}</div>` : '';
  if (yearNote && yearNote.auto && yearNote.year){
    const autoHtml = `<span style="color:#888;margin-left:6px;font-size:0.85em">(auto ${yearNote.year})</span>`;
    deptHtml = snapshot.department ? `<div style="margin-top:4px;font-size:0.9em">${escapeHtml(snapshot.department)} ${autoHtml}</div>` : `<div style="color:#888;margin-top:3px;font-size:0.85em">${autoHtml}</div>`;
  }

  const leftCell = `<div><div style="font-weight:600">${escapeHtml(TARGET_LEAVE_TYPE)}</div>${deptHtml}</div>`;

  let totalAllocated = snapshot.allocated_overrode ? snapshot.allocated_sum : snapshot.entitled;
  let tooltip = snapshot.allocated_overrode ? 'This value comes from Leave Allocation records' : 'Calculated from previous year presence';

  if (snapshot.allocation_draft_only) {
    totalAllocated = `${num(totalAllocated)} <small style="color: #d9822b"> (Draft)</small>`;
    tooltip += ' — allocation(s) present but in Draft status. Server job will submit eligible allocations.';
  } else {
    totalAllocated = num(totalAllocated);
  }

  if (yearNote && yearNote.auto && yearNote.year){
    totalAllocated = `${totalAllocated} <small style="color: #666"> (auto ${yearNote.year})</small>`;
    tooltip += ` — auto-allocated for ${yearNote.year}`;
  }

  const row = `<tr>
    <td style="vertical-align: middle;">${leftCell}</td>
    <td title="${escapeHtml(tooltip)}">${totalAllocated}</td>
    <td>0</td>
    <td>${num(snapshot.taken)}</td>
    <td>${num(snapshot.pending)}</td>
    <td>${num(snapshot.available)}</td>
  </tr>`;
  $tbody.append(row);
}

async function insertAndTrySubmitLeaveAllocation(employee, leave_type, amount, year){
  // Client-side helper: attempts to insert and set docstatus via client APIs.
  // NOTE: This may leave Draft if server side cannot submit; run the Server Script for guaranteed submission.
  let company = null;
  try {
    const emp = await gv('Employee', 'company', { name: employee });
    if (emp && emp.company) company = emp.company;
  } catch(e){ /* ignore */ }

  const doc = {
    doctype: 'Leave Allocation',
    employee,
    leave_type,
    new_leaves_allocated: amount,
    from_date: `${year}-01-01`,
    to_date: `${year}-12-31`,
    allocation_type: 'Fixed',
    carry_forward: 1
  };
  if (company) doc.company = company;

  let inserted = null;
  try {
    inserted = await fcall('frappe.client.insert', { doc });
  } catch (err) {
    console.error('insertLeaveAllocation: insert failed', err);
    throw err;
  }
  const name = inserted && inserted.name ? inserted.name : null;
  if (!name) return { name: null, inserted: false, submitted: false };

  // try set_value to mark submitted (may fail if server doesn't allow)
  let submitted = false;
  try {
    await fcall('frappe.client.set_value', { doctype: 'Leave Allocation', name: name, fieldname: 'docstatus', value: 1 });
    submitted = true;
  } catch (err) {
    // client fallback: try client.submit (may not be available)
    try {
      await fcall('frappe.client.submit', { doctype: 'Leave Allocation', name: name });
      submitted = true;
    } catch (_) {
      submitted = false;
    }
  }

  return { name, inserted: true, submitted };
}

// bind & main
let lastSnap = null;

frappe.ui.form.on('Leave Application', {
  refresh: frm => frm.trigger('update_privilege'),
  employee: frm => frm.trigger('update_privilege'),
  leave_type: frm => frm.trigger('update_privilege'),
  posting_date: frm => frm.trigger('update_privilege'),
  from_date: frm => frm.trigger('update_privilege'),

  validate: async function(frm){
    if (frm.doc.leave_type !== TARGET_LEAVE_TYPE) return;

    const s = lastSnap || {};
    if (!s.eligible){
    frappe.msgprint({
      title: "Not Eligible",
      message: `Earned Leave can be applied only after completing 180 present days from DOJ.`,
      indicator: "red"
    });

    // CRITICAL: stop submit BEFORE server validation
    frappe.validated = false;
      return;
    }


    const from = frm.doc.from_date ? toDate(frm.doc.from_date) : null;
    const to   = frm.doc.to_date ? toDate(frm.doc.to_date) : null;

    if (from && to && from > to) frappe.throw("Invalid date range: 'From Date' must be on or before 'To Date'.");

    let requested = 0;
    if (frm.doc.half_day) {
      requested = 0.5;
    } else if (from && to) {
      requested = frappe.datetime.get_diff(to, from) + 1;
    }

    if (requested > num(s.remaining)){ frappe.throw(`Requested ${requested} exceeds remaining ${num(s.remaining)} (${TARGET_LEAVE_TYPE}).`); }

    // Require at least one submitted allocation overlapping requested period
    if (from && to) {
      const overlaps = await gl('Leave Allocation', {
        employee: frm.doc.employee,
        leave_type: TARGET_LEAVE_TYPE,
        from_date: ['<=', frm.doc.to_date],
        to_date: ['>=', frm.doc.from_date]
      }, ['name'], 20);

      let hasSubmitted = false;
      let hasDraft = false;
      if (overlaps && overlaps.length) {
        for (const a of overlaps) {
          const rec = await get_doc('Leave Allocation', a.name);
          if (rec) {
            if (rec.docstatus === 1) { hasSubmitted = true; break; }
            if (rec.docstatus === 0) { hasDraft = true; }
          }
        }
      }

      if (!hasSubmitted) {
        if (hasDraft) {
          frappe.throw("A Leave Allocation exists for these dates but it is in Draft. Server job or admin must submit the allocation before applications are allowed.");
        } else {
          frappe.throw("Application period cannot be outside leave allocation period");
        }
      }
    }
  },

  update_privilege: frappe.utils.debounce(async function(frm){
    if (!frm.doc.employee){ updateAllocatedTable(null); lastSnap = null; return; }

    lastSnap = await computeSnapshot(frm.doc);
    updateAllocatedTable(lastSnap);

    // ensure Earned Leaves is available in leave_type selector
    frm.set_query('leave_type', function(){ return {}; });

    // client attempt to create allocation if missing (may remain Draft)
    try {
      if (!lastSnap) return;
      const posting = pickAsOfDate(frm.doc) || toDate(frappe.datetime.get_today());
      const year = (posting).getFullYear();

      if (lastSnap.eligible && !lastSnap.allocated_overrode && lastSnap.computed_entitled > 0 && !frm.__auto_allocating) {
        frm.__auto_allocating = true;
        try {
          const existing = await gl('Leave Allocation', { employee: frm.doc.employee, leave_type: TARGET_LEAVE_TYPE, from_date: ['>=', `${year}-01-01`], to_date: ['<=', `${year}-12-31`] }, ['name'], 5);
          if (!existing || existing.length === 0) {
            try {
              const res = await insertAndTrySubmitLeaveAllocation(frm.doc.employee, TARGET_LEAVE_TYPE, lastSnap.computed_entitled, year);
              lastSnap = await computeSnapshot(frm.doc);
              updateAllocatedTable(lastSnap, { year, auto: true });

              if (res && res.inserted) {
                if (res.submitted) {
                  frappe.msgprint(`✅ ${TARGET_LEAVE_TYPE} auto-allocated and submitted (${lastSnap.computed_entitled}) for ${year}.`);
                } else {
                  frappe.msgprint(`⚠️ ${TARGET_LEAVE_TYPE} auto-allocated as Draft (${lastSnap.computed_entitled}) for ${year}. Server job (scheduled) will submit eligible allocations.`);
                }
              }
            } catch (errInsert) {
              console.error('Auto-allocation failed', errInsert);
              lastSnap = await computeSnapshot(frm.doc);
              updateAllocatedTable(lastSnap);
            }
          } else {
            lastSnap = await computeSnapshot(frm.doc);
            updateAllocatedTable(lastSnap);
          }
        } finally { setTimeout(()=>{ frm.__auto_allocating = false; }, 1000); }
      }
    } catch(e){
      console.error('auto-allocation flow failed', e);
      frm.__auto_allocating = false;
    }
  }, 250)
});

