function fetch_and_fill_approvers(frm) {
    // require an employee
    if (!frm.doc.from_employee) return;

    // disable UI briefly
    frm.toggle_enable(false);

    // get department from Employee record (preferred)
    frappe.db.get_value('Employee', frm.doc.from_employee, 'department')
    .then(emp_res => {
        const dept_name = emp_res && emp_res.message && emp_res.message.department;
        if (!dept_name) {
            // no department -> clear table and re-enable
            frm.clear_table('custom_expense_approver_details');
            frm.refresh_field('custom_expense_approver_details');
            frm.set_value('expense_approver', null);
            frm.toggle_enable(true);
            return;
        }

        // fetch Department doc that contains the approver child table
        frappe.db.get_doc('Department', dept_name)
        .then(dept => {
            // candidate child-table fieldnames to try (common variants)
            const candidates = ['expense_approvers', 'expense_approver', 'approvers', 'custom_expense_approvers', 'custom_expense_approver'];

            let approver_rows = [];
            for (let c of candidates) {
                if (Array.isArray(dept[c]) && dept[c].length) {
                    approver_rows = dept[c];
                    break;
                }
            }

            // clear existing rows and populate fresh ones (always overwrite)
            frm.clear_table('custom_expense_approver_details');

            if (approver_rows.length) {
                approver_rows.forEach(r => {
                    // pick the actual value stored in department row
                    const approver_val = r.approver || r.approver_email || r.email || r.user || null;
                    if (approver_val) {
                        const child = frm.add_child('custom_expense_approver_details');
                        child.approver = approver_val;
                        // leave status/date blank
                    }
                });

                // optional: set top-level expense_approver to first approver
                const first = approver_rows[0];
                const firstVal = first && (first.approver || first.approver_email || first.email || first.user);
                if (firstVal) {
                    frm.set_value('expense_approver', firstVal);
                }
            } else {
                // no approvers in department
                frm.set_value('expense_approver', null);
            }

            // refresh UI
            frm.refresh_field('custom_expense_approver_details');
            frm.refresh_field('expense_approver');
            frm.toggle_enable(true);
        })
        .catch(err => {
            // on error clear and re-enable
            console && console.error && console.error(err);
            frm.clear_table('custom_expense_approver_details');
            frm.refresh_field('custom_expense_approver_details');
            frm.toggle_enable(true);
        });

    }).catch(err => {
        console && console.error && console.error(err);
        frm.toggle_enable(true);
    });
}

