function init(frm) {
    const emp = frm.doc.from_employee || frm.doc.employee;
    if (emp) loadApprovers(frm, emp);
    registerHandlers(frm);
}

function loadApprovers(frm, employee) {
    if (!employee) return;
    if (frm.doc.custom_expense_approver_details?.length > 0) return;

    frm.clear_table('custom_expense_approver_details');
    frm.set_value('expense_approver', null);

    frappe.db.get_value('Employee', employee, 'department')
        .then(r => {
            const dept = r?.message?.department;
            if (!dept) {
                frappe.msgprint(__('Selected employee has no Department.'));
                return;
            }

            return frappe.db.get_doc('Department', dept)
                .then(d => {
                    const rows = Array.isArray(d.expense_approvers) ? d.expense_approvers : [];
                    if (!rows.length)
                        return frappe.msgprint(__('No Expense Approvers configured for Department: {0}', [dept]));

                    rows.forEach(rr => {
                        const a = rr.approver || rr.approver_email || rr.email || rr.user || rr.employee;
                        if (a) {
                            const child = frm.add_child('custom_expense_approver_details');
                            // set default status to Draft if you want (optional)
                            // child.status = 'Draft';
                            child.approver = a;
                        }
                    });

                    frm.refresh_field('custom_expense_approver_details');

                    const firstVal = rows[0] && (rows[0].approver || rows[0].approver_email || rows[0].email || rows[0].user || rows[0].employee);
                    if (firstVal) frm.set_value('expense_approver', firstVal);
                })
                .catch(() => frappe.msgprint(__('Unable to fetch Department. Check permissions.')));
        });
}

function getApprover(row) {
    return row && (row.approver || row.approver_email || row.email || row.user || row.employee) || null;
}

function registerHandlers(frm) {
    const f = frm.fields_dict?.['custom_expense_approver_details'];
    if (!f?.grid) return;
    const child = f.grid.doctype;

    // avoid duplicate registration when multiple forms open
    if (frappe._registered_approver_child === child) return;
    frappe._registered_approver_child = child;

    frappe.ui.form.on(child, {
        status(frm_child, cdt, cdn) {
            const row = locals[cdt][cdn];
            if (!row) return;
            const a = getApprover(row);
            if (a) frm.set_value('expense_approver', a);
            recompute(frm);
        },
        approver(frm_child, cdt, cdn) {
            const row = locals[cdt][cdn];
            if (!row) return;
            const a = getApprover(row);
            if (a) frm.set_value('expense_approver', a);
            recompute(frm);
        },
        // also recompute if a row is added/removed
        row_added(frm_child, cdt, cdn) {
            recompute(frm);
        },
        row_removed(frm_child, cdt, cdn) {
            recompute(frm);
        }
    });
}

function recompute(frm) {
    // If manual approval is checked, respect it (Approved) and skip table logic
    if (isManualChecked(frm)) {
        setDocStatus(frm, 'Approved');
        return;
    }

    const rows = frm.doc.custom_expense_approver_details || [];
    if (!rows.length) {
        // No approvers configured -> treat as Rejected (or you can choose Draft)
        setDocStatus(frm, 'Rejected');
        return;
    }

    // If any row is Draft / empty → overall should be Draft
    const any_draft = rows.some(r => {
        const s = (r.status || '').toString().trim().toLowerCase();
        // treat empty string or explicit 'draft' as Draft
        return !s || s === 'draft';
    });

    if (any_draft) {
        setDocStatus(frm, 'Draft');
        return;
    }

    // Only approve if every row is Approved (case-insensitive)
    const all_approved = rows.every(r => (r.status || '').toString().trim().toLowerCase() === 'approved');

    const new_status = all_approved ? 'Approved' : 'Rejected';
    setDocStatus(frm, new_status);
}

function setDocStatus(frm, new_status) {
    frm.set_value('approval_status', new_status);

    // Disable submit only if field exists
    if (frm.fields_dict?.custom_disable_submit) {
        // if Approved -> enable submit (0), else disable (1)
        frm.set_value('custom_disable_submit', new_status === 'Approved' ? 0 : 1);
        frm.refresh_field('custom_disable_submit');
    }

    frm.refresh_field('approval_status');
}

// ---------- Manual approval helpers ----------

// Returns the manual checkbox fieldname that exists on the form (or null)
function manualField() {
    // prefer explicit 'manual_approval' if present, else 'custom_manual_approval'
    if (typeof cur_frm?.doc?.manual_approval !== 'undefined') return 'manual_approval';
    if (typeof cur_frm?.doc?.custom_manual_approval !== 'undefined') return 'custom_manual_approval';
    return null;
}

// Check if manual checkbox is checked (works with either fieldname)
function isManualChecked(frm) {
    const mf = manualField();
    if (!mf) return false;
    return !!(frm.doc[mf]);
}

// Called when manual checkbox toggles
function handleManualToggle(frm) {
    const mf = manualField();
    if (!mf) return; // nothing to do if no checkbox present

    const checked = !!frm.doc[mf];

    if (checked) {
        // Immediately set Approved and enable submit
        setDocStatus(frm, 'Approved');
    } else {
        // Recompute status from table now that manual approval removed
        recompute(frm);
    }
}

// Apply manual state on load/refresh
function applyManualStateIfNeeded(frm) {
    const mf = manualField();
    if (!mf) return;
    if (frm.doc[mf]) {
        // If manual approval is currently checked, enforce Approved state
        setDocStatus(frm, 'Approved');
    } else {
        // If unchecked, recompute (so saving after unchecking will update status)
        recompute(frm);
    }
}

// Leave Allocation — auto-fill total_leaves_allocated from attendance (current-year only)
const PRESENT_STATUSES = ['Present', 'Work From Home', 'On Duty'];

function num(x){ return x==null?0:(typeof x==='number'?x:(parseFloat(x)||0)); }
function toDate(val){
  if (!val) return null;
  if (val instanceof Date) return val;
  try { return frappe.datetime.str_to_obj(val); } catch(e){ return null; }
}
function iso(d){ if(!d) return null; return frappe.datetime.obj_to_str(d); }

function customEntitlementRound(x){
  if (x == null) return 0;
  const n = Number(x);
  if (!isFinite(n)) return 0;
  const sign = n < 0 ? -1 : 1;
  const abs = Math.abs(n);
  const intPart = Math.floor(abs);
  const dec = +(abs - intPart).toFixed(3);
  if (dec < 0.45) return sign * intPart;
  if (dec < 0.55) return sign * (intPart + 0.5);
  return sign * (intPart + 1);
}

// count attendance days in date range (docstatus 0 & 1)
async function countAttendanceDays(employee, startISO, endISO){
  if (!employee || !startISO || !endISO) return 0;
  let total = 0;
  for (const st of PRESENT_STATUSES){
    const res1 = await new Promise(resolve => {
      frappe.call({
        method: 'frappe.client.get_count',
        args: { doctype: 'Attendance', filters: { employee, status: st, attendance_date: ['between', [startISO, endISO]], docstatus: 1 } },
        callback: r => resolve(r && r.message || 0)
      });
    }).catch(()=>0);
    const res0 = await new Promise(resolve => {
      frappe.call({
        method: 'frappe.client.get_count',
        args: { doctype: 'Attendance', filters: { employee, status: st, attendance_date: ['between', [startISO, endISO]], docstatus: 0 } },
        callback: r => resolve(r && r.message || 0)
      });
    }).catch(()=>0);
    total += (res1 || 0) + (res0 || 0);
  }
  return total;
}

async function computeAndSetAllocation(frm){
  try {
    const emp = frm.doc.employee;
    if (!emp) return;

    // current year as understood by browser
    const serverTodayStr = frappe.datetime.get_today();
    const serverTodayObj = toDate(serverTodayStr) || new Date();
    const currentYear = (serverTodayObj instanceof Date) ? serverTodayObj.getFullYear() : (new Date(serverTodayObj)).getFullYear();

    // compute entitlement from previous calendar year
    const prevYear = currentYear - 1;
    const prevStartISO = iso(toDate(`${prevYear}-01-01`));
    const prevEndISO   = iso(toDate(`${prevYear}-12-31`));
    const presentDays = await countAttendanceDays(emp, prevStartISO, prevEndISO);
    const entitled_raw = presentDays / 20.0;
    const computed_entitled = customEntitlementRound(entitled_raw);

    // ensure allocation targets currentYear
    let docFrom = frm.doc.from_date ? toDate(frm.doc.from_date) : null;
    let docTo   = frm.doc.to_date   ? toDate(frm.doc.to_date)   : null;

    if (!docFrom && !docTo) {
      const setFrom = `${currentYear}-01-01`;
      const setTo   = `${currentYear}-12-31`;
      frm.set_value('from_date', setFrom);
      frm.set_value('to_date', setTo);
      docFrom = toDate(setFrom);
      docTo = toDate(setTo);
    }

    const fromYear = docFrom ? (docFrom.getFullYear ? docFrom.getFullYear() : (new Date(docFrom)).getFullYear()) : null;
    if (fromYear !== currentYear) {
      if (frm.dashboard && frm.dashboard.show_message) {
        frm.dashboard.show_message(`Allocation targets ${fromYear || 'unknown'} — auto-calculation applies only for current year ${currentYear}.`);
      }
      return;
    }

    // set values only when empty/zero
    const current_total = num(frm.doc.total_leaves_allocated);
    const current_new = num(frm.doc.new_leaves_allocated);

    if (!current_total) frm.set_value('total_leaves_allocated', computed_entitled);
    if (!current_new) {
      if (frm.fields_dict && frm.fields_dict.new_leaves_allocated) {
        frm.set_value('new_leaves_allocated', computed_entitled);
      } else {
        frm.doc.new_leaves_allocated = computed_entitled;
      }
    }

    if (frm.dashboard && frm.dashboard.show_message) {
      frm.dashboard.show_message(`Auto-calculated from ${prevYear}: ${presentDays} days → ${computed_entitled} leaves (applied to ${currentYear})`);
    }
    frm.refresh_field && frm.refresh_field('total_leaves_allocated');
    frm.refresh_field && frm.refresh_field('new_leaves_allocated');

  } catch (e) {
    console.error('computeAndSetAllocation error', e);
  }
}

