// Client Script for Leave Application (Client)
// DocType: Leave Application
// Paste this into a Client Script record for Leave Application.

(function() {
  // utility: build a comparable timestamp key for a row
  function row_ts_key(row) {
    if (!row) return "";
    if (row.date) return String(row.date);
    if (row.modified || row.modified_on) return String(row.modified || row.modified_on);
    return "IDX-" + String(row.idx || 0).padStart(6, "0");
  }

  // choose last approver from rows (latest row that has approver or modified_by)
  function pick_last_approver(rows) {
    if (!rows || !rows.length) return null;
    let best = null;
    let best_key = null;
    rows.forEach(r => {
      if (!r) return;
      if (!r.approver && !r.modified_by && !r.approver_name) return;
      const k = row_ts_key(r);
      if (!best_key || k > best_key) {
        best_key = k;
        best = r;
      }
    });
    return { row: best, ts: best_key };
  }

  // determine overall status from child rows (same rules as server)
  function compute_status_from_rows(rows) {
    if (!rows || !rows.length) return null;
    let any_rows = false;
    let any_other = false;
    let any_rejected = false;
    rows.forEach(r => {
      any_rows = true;
      const s = (r.status || "").toString().trim();
      if (s && s !== "Approved" && s !== "Rejected") {
        any_other = true;
      }
      if (s === "Rejected") {
        any_rejected = true;
      }
    });
    if (any_other) return "Open";
    if (any_rejected) return "Rejected";
    return any_rows ? "Approved" : null;
  }

  // helper: safely set custom_disable_submit only if field exists
  function safe_set_custom_disable_submit(frm, value) {
    try {
      if (frm.fields_dict && frm.fields_dict.custom_disable_submit) {
        frm.set_value("custom_disable_submit", value);
      }
    } catch (e) { /* ignore */ }
  }

  // main updater: update leave_approver, leave_approver_name, status, custom_disable_submit
  function update_from_table(frm) {
    const rows = (frm.doc.custom_leave_approver_details || []).slice();
    // pick last approver row
    const last = pick_last_approver(rows);
    if (last && last.row) {
      const approverId = last.row.approver || last.row.modified_by;
      if (approverId && approverId !== frm.doc.leave_approver) {
        frm.set_value("leave_approver", approverId);
      }
      if (last.row.approver_name && last.row.approver_name !== frm.doc.leave_approver_name) {
        frm.set_value("leave_approver_name", last.row.approver_name);
      }
    }

    // If manual-check is enabled -> do not auto-change when already checked (but we still set Approved when newly checked in the handler)
    if (frm.doc.custom_check) {
      // keep current status as-is (but ensure submit flag follows status)
      if (frm.doc.status === "Approved") {
        safe_set_custom_disable_submit(frm, 0);
      } else {
        safe_set_custom_disable_submit(frm, 1);
      }
      return;
    }

    // compute status from rows if manual-check is not checked
    const auto_status = compute_status_from_rows(rows);
    if (auto_status) {
      if (auto_status !== frm.doc.status) {
        frm.set_value("status", auto_status);
      }
      // submit control
      safe_set_custom_disable_submit(frm, auto_status === "Approved" ? 0 : 1);
    }
  }

  // Called when custom_check toggles: newly checked -> auto-approve immediately
  function handle_custom_check_change(frm) {
    if (frm.doc.custom_check) {
      // set Approved immediately
      frm.set_value("status", "Approved");
      safe_set_custom_disable_submit(frm, 0);

      // set leave_approver to current user if empty
      if (!frm.doc.leave_approver) {
        frm.set_value("leave_approver", frappe.session.user);
        // fetch full name asynchronously for approver_name (best-effort)
        frappe.call({
          method: "frappe.client.get",
          args: { doctype: "User", name: frappe.session.user },
          callback: function(r) {
            if (r && r.message && r.message.full_name) {
              frm.set_value("leave_approver_name", r.message.full_name);
            }
          }
        });
      }
    } else {
      // unchecked -> recompute status from table immediately
      update_from_table(frm);
    }
  }

  // attach event handlers
  frappe.ui.form.on("Leave Application", {
    refresh: function(frm) {
      update_from_table(frm);

      try {
        const grid = frm.fields_dict && frm.fields_dict["custom_leave_approver_details"] && frm.fields_dict["custom_leave_approver_details"].grid;
        if (grid && !grid._custom_listeners_attached) {
          grid._custom_listeners_attached = true;

          grid.wrapper.on("grid-row-render", function() {
            setTimeout(function() { update_from_table(frm); }, 50);
          });

          grid.wrapper.on("change", function() {
            setTimeout(function() { update_from_table(frm); }, 50);
          });

          grid.wrapper.on("click", function() {
            setTimeout(function() { update_from_table(frm); }, 50);
          });
        }
      } catch (e) { /* ignore */ }
    },

    custom_check: function(frm) {
      handle_custom_check_change(frm);
    },

    status: function(frm) {
      try {
        if (frm.doc.status === "Approved") {
          safe_set_custom_disable_submit(frm, 0);
        } else {
          safe_set_custom_disable_submit(frm, 1);
        }
      } catch (e) { /* ignore */ }
    }
  });

  // Child-doctype handler: replace "Custom Leave Approver Details" with your real child doctype name if needed.
  frappe.ui.form.on("Custom Leave Approver Details", {
    status: function(frm, cdt, cdn) { update_from_table(frm); },
    approver: function(frm, cdt, cdn) { update_from_table(frm); },
    approver_name: function(frm, cdt, cdn) { update_from_table(frm); },
    date: function(frm, cdt, cdn) { update_from_table(frm); },
    custom_leave_approver_details_add: function(frm, cdt, cdn) { update_from_table(frm); },
    custom_leave_approver_details_remove: function(frm, cdt, cdn) { update_from_table(frm); }
  });

})();

