// ----------------------- HIDE ACTION BUTTON (DON'T REMOVE MENU ITEMS) -----------------------
function hide_actions_button_only() {
    try {
        // Find dropdown toggles/buttons used as "Action" toggles in page head / page actions / navbar
        // Common selectors: .dropdown-toggle, .btn.dropdown-toggle, .page-actions .btn
        $('.page-actions, .page-head, .navbar').each(function () {
            const $container = $(this);

            // find each dropdown toggle inside container
            $container.find('.dropdown-toggle, [data-toggle="dropdown"], .btn-action, .btn.dropdown-toggle').each(function () {
                const $toggle = $(this);
                // find the related dropdown menu; try common DOM relationships
                let $menu = $toggle.siblings('.dropdown-menu');
                if (!$menu || !$menu.length) {
                    // some layouts put the menu elsewhere — try parent then descend
                    $menu = $toggle.parent().find('.dropdown-menu');
                }
                if (!$menu || !$menu.length) {
                    // last resort: look for any nearby dropdown-menu
                    $menu = $container.find('.dropdown-menu').first();
                }
                if (!$menu || !$menu.length) return;

                // Check if the menu contains any of the unwanted items (case-insensitive)
                let hasUnwanted = false;
                $menu.find('a, button, li').each(function () {
                    const txt = ($(this).text() || '').trim().toLowerCase();
                    if (!txt) return;
                    if (
                        txt.includes('preview letter') ||
                        txt.includes('print letter') ||
                        txt.includes('print letter (pdf)')
                    ) {
                        hasUnwanted = true;
                        return false; // break out of .each
                    }
                });

                // If unwanted items exist, hide the toggle/action button (but do not remove menu items)
                if (hasUnwanted) {
                    // Hide the toggle btn — prefer visually hiding without removing from DOM
                    $toggle.css({
                        'display': 'none',
                        'visibility': 'hidden'
                    });

                    // If the toggle is inside an li or button-group, hide that too to avoid empty space
                    const $parentLi = $toggle.closest('li, .btn-group, .page-actions-wrapper, .btn');
                    if ($parentLi.length) {
                        $parentLi.css({
                            'display': 'none',
                            'visibility': 'hidden'
                        });
                    }
                }
            });
        });
    } catch (e) {
        console.warn('Error hiding action button:', e);
    }
}

// Keep watching in case menu re-renders
let __menu_observer;
function observe_action_menu() {
    if (__menu_observer) return; // avoid duplicates

    const target = document.body;
    if (!target) return;

    __menu_observer = new MutationObserver(() => {
        // on any DOM change, try hiding the action button again
        hide_actions_button_only();
    });

    __menu_observer.observe(target, { childList: true, subtree: true });

    // run once after short delay for initial render cases
    setTimeout(hide_actions_button_only, 400);
}

// ----------------------- DUPLICATE TEMPLATE CHECK -----------------------
function check_duplicate_template(frm, template_fieldname) {
    if (!frm.fields_dict[template_fieldname] || !frm.doc[template_fieldname]) return;

    const applicant = frm.doc.job_applicant;
    if (!applicant) return;

    frappe.db.get_list('Appointment Letter', {
        filters: [
            ['job_applicant', '=', applicant],
            [template_fieldname, '=', frm.doc[template_fieldname]],
            ['name', '!=', frm.doc.name || ''],
            ['docstatus', '!=', 2]
        ],
        fields: ['name'],
        limit_page_length: 1
    }).then(results => {
        if (results && results.length) {
            const existing = results[0];
            // Show warning only — no confirmation or creation option
            frappe.msgprint({
                title: __('Duplicate Letter'),
                message: __(
                    `⚠️ A letter with this template for this job applicant already exists.<br><b>Existing Document:</b> ${existing.name}`
                ),
                indicator: 'red'
            });

            // Clear the field immediately
            frm.set_value(template_fieldname, null);
            frm.refresh_field(template_fieldname);
        }
    }).catch(err => {
        console.error('Error checking duplicate Appointment Letter', err);
    });
}

