            frappe.call({
                method: "frappe.client.insert",
                freeze: true,
                args: {
                    doc: {
                        doctype: "Item",
                        item_code: title,
                        item_name: title,
                        description: title,
                        custom_part_type: "Special Item",
                        custom_material: materials_val,
                        custom_design: designs_val,
                        custom_w: Number(v.custom_w || 0),
                        custom_d: Number(v.custom_d || 0),
                        custom_h: Number(v.custom_h || 0),
                        custom_t: Number(v.custom_t || 0),
                        gst_hsn_code: hsn_val,
                        is_stock_item: 1,
                        maintain_stock: 1,
                        item_group: "Custom Products",
                    },
                },
                callback: (r) => {
                    const doc = r && r.message;
                    if (!doc) return frappe.msgprint(__("Failed to create Item."));
                    frappe.show_alert(
                        {
                            message: `🆕 Item <b>${frappe.utils.escape_html(doc.name)}</b> created`,
                            indicator: "green",
                        },
                        5
                    );
                    open_qty_and_add(doc.name);
                },
            });
        }

        // ===== BUILD FILTERS =====
        function build_filters_and_search() {
            const v = dialog.get_values(true) || {};
            const design = v.custom_designs;
            const material = v.custom_materials;

            const toNum = (x) => (x === 0 ? 0 : x === "" || x === undefined || x === null ? null : Number(x));
            const w = toNum(v.custom_w);
            const d = toNum(v.custom_d);
            const h = toNum(v.custom_h);
            const t = toNum(v.custom_t);

            const all_dims = w !== null && d !== null && h !== null && t !== null;
            const any_basic = !!(design || material || w !== null || d !== null || h !== null || t !== null);

            let filters = [["Item", "disabled", "!=", 1]];
            let or_filters = [];

            filters.push(["Item", "item_group", "in", window._product_item_groups || ["Products"]]);

            const addTol = (fieldname, val) => {
                if (val === null || Number.isNaN(val)) return;
                const vnum = Number(val);
                if (vnum === 0) {
                    filters.push(["Item", fieldname, "=", 0]);
                    return;
                }
                const tol = Math.abs(vnum) * 0.002;
                filters.push(["Item", fieldname, ">=", vnum - tol]);
                filters.push(["Item", fieldname, "<=", vnum + tol]);
            };

            if (all_dims) {
                addTol("custom_w", w);
                addTol("custom_d", d);
                addTol("custom_h", h);
                addTol("custom_t", t);
                if (design) filters.push(["Item", "custom_design", "=", design]);
                if (material) filters.push(["Item", "custom_material", "=", material]);
            } else if (any_basic) {
                if (design) filters.push(["Item", "custom_design", "=", design]);
                if (material) filters.push(["Item", "custom_material", "=", material]);
                addTol("custom_w", w);
                addTol("custom_d", d);
                addTol("custom_h", h);
                addTol("custom_t", t);
            }

            const q = (searchText || "").trim();
            if (q) {
                q.split(/\s+/)
                    .filter(Boolean)
                    .forEach((p) => {
                        const like = `%${p}%`;
                        or_filters.push(["Item", "item_code", "like", like]);
                        or_filters.push(["Item", "item_name", "like", like]);
                        or_filters.push(["Item", "description", "like", like]);
                        or_filters.push(["Item", "custom_catalog_no", "like", like]);
                        or_filters.push(["Item", "item_group", "like", like]);
                    });
            }

            return { filters, or_filters };
        }

        let page_start = 0;
        const page_len = 20;
        let loading = false;

        function html_to_text(html) {
            if (!html) return "";
            return $("<div>").html(html).text().trim();
        }

        // ===== RENDER LIST =====
        function render_list(items, append = false, has_more = false) {
            const $wrap = dialog.fields_dict.filtered_results_html.$wrapper;
            if (!append) $wrap.empty();

            const filteredCtrl = dialog.fields_dict.filtered_item_code;
            const currentTyped = filteredCtrl && filteredCtrl.$input ? filteredCtrl.$input.val() : "";

            if (!append && (!items || !items.length)) {
                createMode = false;
                set_fields_required(false);
                hide_hsn_field();
                dialog.set_df_property(
                    "filtered_item_code",
                    "placeholder",
                    "Type to search item code/name/description"
                );
                $wrap.append('<div style="color:#888;margin-top:6px;">No items found.</div>');
                if (filteredCtrl && filteredCtrl.$input) filteredCtrl.$input.val(currentTyped);
                return;
            }

            if (append || (items && items.length)) {
                createMode = false;
                set_fields_required(false);
                hide_hsn_field();
                dialog.set_df_property(
                    "filtered_item_code",
                    "placeholder",
                    "Type to search item code/name/description/item group"
                );
            }

            const $list = append
                ? $wrap.find(".inline-item-list")
                : $(
                      '<div class="inline-item-list" style="max-height:260px; overflow:auto; margin-top:8px; border:1px solid #eee; border-radius:6px;"></div>'
                  );
            if (!append) $wrap.append($list);

            items.forEach((r) => {
                const code = r.item_code || r.name;
                const name = r.item_name || "";
                const desc = html_to_text(r.description);
                const group = r.item_group || "";

                const $row = $(`
                    <div class="inline-item-row" style="padding:10px 12px; display:flex; gap:12px; align-items:flex-start; cursor:pointer; border-bottom:1px solid #f0f0f0;">
                        <div style="min-width:200px; display:flex; flex-direction:column;">
                            <div style="font-weight:600;">${frappe.utils.escape_html(code)}</div>
                            ${
                                group
                                    ? `<div style="font-size:11px;color:#888;margin-top:4px;">${frappe.utils.escape_html(
                                          group
                                      )}</div>`
                                    : ""
                            }
                        </div>
                        <div style="flex:1;">
                            <div style="font-size:12px;color:#444;">${frappe.utils.escape_html(name)}</div>
                            ${
                                desc
                                    ? `<div style="font-size:11px;color:#777;margin-top:2px;">${frappe.utils.escape_html(
                                          desc
                                      )}</div>`
                                    : ""
                            }
                        </div>
                        <div style="font-size:12px; color:#0b69ff; min-width:48px; text-align:right;">Select</div>
                    </div>
                `);
                $row.on("click", () => open_qty_and_add(r.name));
                $list.append($row);
            });

            $wrap.find(".inline-more").remove();
            if (has_more) {
                const $more = $(
                    '<div class="inline-more" style="margin-top:8px;"><button class="btn btn-sm btn-default">More</button></div>'
                );
                $more.find("button").on("click", () => fetch_and_render(true));
                $wrap.append($more);
            }

            if (filteredCtrl && filteredCtrl.$input) filteredCtrl.$input.val(currentTyped);
        }

        // ===== FETCH AND RENDER =====
        function fetch_and_render(append = false) {
            if (loading) return;
            loading = true;

            const start = append ? page_start : 0;
            if (!append) page_start = 0;

            const { filters, or_filters } = build_filters_and_search();

            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Item",
                    fields: ["name", "item_code", "item_name", "description", "item_group"],
                    filters,
                    or_filters,
                    limit_start: start,
                    limit_page_length: page_len + 1,
                },
                callback: (r) => {
                    const rows = (r && r.message) || [];
                    const has_more = rows.length > page_len;
                    const slice = rows.slice(0, page_len);
                    if (append) page_start += slice.length;
                    else page_start = slice.length;
                    render_list(slice, append, has_more);
                },
                always: () => {
                    loading = false;
                },
            });
        }

        (async function preload_item_groups() {
            window._product_item_groups = await get_item_group_with_children("Products");
        })();

        fetch_and_render(false);

        // ===== BIND FILTER WATCHERS =====
        (function bindFilterWatchers() {
            const linkFields = ["custom_designs", "custom_materials"];
            const dims = ["custom_w", "custom_d", "custom_h", "custom_t"];

            function refetch() {
                page_start = 0;
                fetch_and_render(false);
            }

            linkFields.forEach((fn) => {
                const ctrl = dialog.fields_dict[fn];
                if (!ctrl || !ctrl.$input) return;
                ctrl.$input.on("change blur", refetch);
                ctrl.$input.on("awesomplete-selectcomplete awesomplete-close", refetch);
                try {
                    ctrl.$input.on("select2:select", refetch);
                } catch (e) {}
            });

            dims.forEach((fn) => {
                const ctrl = dialog.fields_dict[fn];
                if (!ctrl || !ctrl.$input) return;
                ctrl.$input.on("change blur", refetch);
            });
        })();

        // ===== HOOK SEARCH TYPING =====
        (function hookSearchTyping() {
            const f = dialog.fields_dict.filtered_item_code;
            if (!f || !f.$input) return;
            let t;
            f.$input.on("input change", () => {
                if (createMode) {
                    searchText = (f.$input.val() || "").trim();
                    return;
                }
                clearTimeout(t);
                t = setTimeout(() => {
                    searchText = (f.$input.val() || "").trim();
                    fetch_and_render(false);
                }, 200);
            });
        })();

        // ===== DESCRIPTION HELPERS =====
        function to_description_html(text) {
            if (!text) return "";
            const t = String(text).trim();
            if (!t) return "";
            if (t.indexOf("<") !== -1) return t;
            return t
                .split(/\r?\n/)
                .map((line) => `<div>${frappe.utils.escape_html(line)}</div>`)
                .join("");
        }

        async function force_set_description(row, desc_html) {
            if (!row || !desc_html) return;

            locals[row.doctype][row.name].description = desc_html;
            await frappe.model.set_value(row.doctype, row.name, "description", desc_html);

            try {
                const grid = frm.fields_dict.items.grid;
                const grid_row = grid.grid_rows_by_docname[row.name];
                if (grid_row && grid_row.grid_form && grid_row.grid_form.fields_dict.description) {
                    grid_row.grid_form.fields_dict.description.set_value(desc_html);
                    grid_row.grid_form.refresh_field("description");
                }
            } catch (e) {}

            frm.refresh_field("items");
            frm.dirty();
        }

        // ===== OPEN QTY AND ADD =====
        async function open_qty_and_add(item_code_or_name) {
            if (!item_code_or_name || !item_code_or_name.trim()) {
                frappe.msgprint(__("Invalid item code."));
                return;
            }

            const item_name = item_code_or_name.trim();
            frappe.show_alert(
                {
                    message: `🔄 Fetching rates for <b>${frappe.utils.escape_html(item_name)}</b>...`,
                    indicator: "blue",
                },
                4
            );

            try {
                const [rates, item_details] = await Promise.all([
                    get_item_rates(item_name),
                    frappe.db.get_value("Item", item_name, [
                        "name",
                        "item_name",
                        "description",
                        "stock_uom",
                        "custom_w",
                        "custom_d",
                        "custom_h",
                        "custom_t",
                        "custom_design",
                        "custom_material",
                    ]),
                ]);

                const item =
                    item_details && item_details.message
                        ? item_details.message
                        : {
                              name: item_name,
                              item_name: item_name,
                              description: "",
                              stock_uom: "Nos",
                              custom_w: 0,
                              custom_d: 0,
                              custom_h: 0,
                              custom_t: 0,
                              custom_design: "",
                              custom_material: "",
                          };

                const qty_dialog = new frappe.ui.Dialog({
                    title: `Add ${frappe.utils.escape_html(item.name)}`,
                    fields: [{ label: "Quantity", fieldname: "qty", fieldtype: "Float", reqd: 1, default: 1 }],
                    primary_action_label: "Add Item",
                    primary_action: async function (values) {
                        const qty = flt(values.qty, 2);
                        if (!qty || qty <= 0) {
                            frappe.msgprint(__("Please enter a valid quantity greater than 0."));
                            return false;
                        }
                        await add_item_to_child(item, qty, rates.rate, dialog.get_values(true) || {});
                        qty_dialog.hide();
                        dialog.hide();
                    },
                });

                const $qw = qty_dialog.$wrapper;
                if (typeof $qw.modal === "function") $qw.modal({ backdrop: "static", keyboard: false });
                qty_dialog.show();

                frappe.show_alert(
                    {
                        message: `✅ Ready! Rate: ${
                            rates.rate ? `₹${rates.rate.toLocaleString("en-IN")}` : "Manual entry"
                        }`,
                        indicator: rates.rate > 0 ? "green" : "orange",
                    },
                    3
                );
            } catch (error) {
                console.error("❌ Error:", error);
                open_qty_dialog_fallback({
                    name: item_name,
                    item_name: item_name,
                    description: "",
                    stock_uom: "Nos",
                });
            }
        }

        function open_qty_dialog_fallback(item) {
            const qty_dialog = new frappe.ui.Dialog({
                title: `Manual Entry - ${frappe.utils.escape_html(item.name)}`,
                fields: [
                    { label: "Quantity", fieldname: "qty", fieldtype: "Float", reqd: 1, default: 1 },
                    { label: "Rate (₹)", fieldname: "rate", fieldtype: "Currency", reqd: 1, default: 0 },
                ],
                primary_action_label: "Add Item",
                primary_action: async function (values) {
                    const qty = flt(values.qty);
                    const rate = flt(values.rate);
                    if (!qty || qty <= 0 || rate < 0) {
                        frappe.msgprint(__("Please enter valid quantity and rate."));
                        return false;
                    }
                    await add_item_to_child(item, qty, rate, dialog.get_values(true) || {});
                    qty_dialog.hide();
                    dialog.hide();
                },
            });
            const $qw = qty_dialog.$wrapper;
            if (typeof $qw.modal === "function") $qw.modal({ backdrop: "static", keyboard: false });
            qty_dialog.show();
        }

        // ===== ADD ITEM TO CHILD TABLE =====
        async function add_item_to_child(item, qty, rate, dialog_values) {
            let row = find_first_empty_row() || frm.add_child("items");

            // Always re-fetch description from Item master
            let raw_desc = item.description || "";
            try {
                const item_doc = await frappe.db.get_doc("Item", item.name);
                if (item_doc && item_doc.description) {
                    raw_desc = item_doc.description;
                }
            } catch (e) {
                console.warn("Could not get_doc Item for description", e);
            }

            const desc_html = to_description_html(raw_desc || item.item_name || item.name || "");

            // A) item_code first (triggers ERPNext get_item_details)
            await frappe.model.set_value(row.doctype, row.name, "item_code", item.name);

            // B) wait for get_item_details to finish
            await new Promise((resolve) => setTimeout(resolve, 800));

            // C) set qty/rate/custom fields
            const v = dialog_values || {};
            await frappe.model.set_value(row.doctype, row.name, {
                item_name: item.item_name || item.name,
                qty: qty,
                rate: rate,
                price_list_rate: rate,
                amount: flt(qty * rate, 2),
                stock_uom: item.stock_uom || "Nos",
                uom: item.stock_uom || "Nos",
                conversion_factor: 1,
                custom_w: parseFloat(item.custom_w || v.custom_w || 0),
                custom_d: parseFloat(item.custom_d || v.custom_d || 0),
                custom_h: parseFloat(item.custom_h || v.custom_h || 0),
                custom_t: parseFloat(item.custom_t || v.custom_t || 0),
                custom_designs: item.custom_design || v.custom_designs || "",
                custom_design: item.custom_design || v.custom_designs || "",
                custom_materials: item.custom_material || v.custom_materials || "",
                custom_material: item.custom_material || v.custom_materials || "",
                custom_customer_product_code: parseInt(v.customer_product_code || 0, 10),
            });

            // D) set description LAST
            await force_set_description(row, desc_html);

            // E) delayed force (covers late get_item_details callbacks)
            setTimeout(async () => {
                await force_set_description(row, desc_html);
                frappe.show_alert(
                    {
                        message: `✅ <b>${frappe.utils.escape_html(item.name)}</b> | Qty: ${qty} | Rate: ₹${rate.toLocaleString(
                            "en-IN"
                        )}`,
                        indicator: "green",
                    },
                    3
                );
            }, 500);
        }

        function find_first_empty_row() {
            if (!frm.doc.items || !frm.doc.items.length) return null;
            return frm.doc.items.find((r) => !r.item_code && !r.item_name && !r.qty) || null;
        }
    },

    refresh(frm) {
        if (frm.doc.docstatus === 1) {
            try {
                if (frm.fields_dict?.items?.grid) {
                    const $grid = frm.fields_dict.items.grid.wrapper;
                    $grid.find(".grid-add-row, .grid-add-multiple-rows").hide();
                }
            } catch (e) {}
        }
    },
});

function ensureToastBottomRight() {
    if (document.getElementById("toast-bottom-right-style")) return;
    const style = document.createElement("style");
    style.id = "toast-bottom-right-style";
    style.textContent = `
        .frappe-toast-container {
            position: fixed !important;
            right: 16px !important;
            left: auto !important;
            bottom: 16px !important;
            top: auto !important;
            z-index: 1061 !important;
        }`;
    document.head.appendChild(style);
}






































































