frappe.ui.form.on('Item', {
    custom_development_size_a: recalc_all,
    custom_development_size_b: recalc_all,
    custom_t: recalc_all,
    custom_density: recalc_all,

    calculate_area: (frm) => {
        if (frm.doc.custom_development_size_a && frm.doc.custom_development_size_b) {
            frm.set_value('custom_area',
                (frm.doc.custom_development_size_a * frm.doc.custom_development_size_b) / 1000000);
        }
    },

    calculate_weight: function(frm) {
        if (frm.doc.custom_development_size_a && frm.doc.custom_development_size_b && frm.doc.custom_t && frm.doc.custom_density) {
            frm.set_value('weight_per_unit',
                (frm.doc.custom_development_size_a * frm.doc.custom_development_size_b * frm.doc.custom_t * frm.doc.custom_density) / 1000000);
        }
    }
});

function recalc_all(frm) {
    frm.trigger('calculate_area');
    frm.trigger('calculate_weight');
}

