// === Drawing Revision — keep entered "drawing_revision" unchanged ===
frappe.ui.form.on('Drawing Revision', {
  drawing_revision(frm, cdt, cdn) {
    // no transform; just reassign to itself so grids refresh cleanly
    const row = frappe.get_doc(cdt, cdn);
    row.drawing_revision = row.drawing_revision;
    frm.refresh_field('drawing_revision');
  }
});

// Quotation – hide ONLY "Sales Order" from Create menu
frappe.ui.form.on("Quotation", {
    refresh(frm) {
        // Start observer only once
        if (!window.__quotation_so_observer_started) {
            window.__quotation_so_observer_started = true;
            start_sales_order_menu_observer();
        }

        // Also try once on every refresh (in case menu is already there)
        remove_sales_order_from_create();
    }
});

// Remove the "Sales Order" entry from any open dropdown
function remove_sales_order_from_create() {
    const items = document.querySelectorAll(
        '.dropdown-menu .dropdown-item, .dropdown-menu [role="menuitem"], .dropdown-menu a'
    );

    items.forEach(el => {
        const text = (el.innerText || el.textContent || "").trim().toLowerCase();
        if (text === "sales order") {
            const li = el.closest("li") || el;
            li.remove();
        }
    });
}

// Watch for menu being rendered (React re-renders etc.)
function start_sales_order_menu_observer() {
    const observer = new MutationObserver(() => {
        remove_sales_order_from_create();
    });

    observer.observe(document.body, {
        childList: true,
        subtree: true,
    });

    window.__quotation_so_observer = observer;
}

