            frm.doc.custom_request_no &&
            (!frm.doc.items || !frm.doc.items.length)
        ) {
            fetch_from_request(frm);
        }
    }
});

function fetch_from_request(frm) {
    if (!frm.doc.custom_request_no) return;

    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Material Request",
            name: frm.doc.custom_request_no
        },
        callback(r) {
            if (!r.message) return;

            const mr = r.message;

            // -------------------------------
            // HEADER
            // -------------------------------
            if (mr.custom_customer_name) {
                frm.set_value("customer", mr.custom_customer_name);
            }

            frm.set_value("po_no", mr.custom_customer_po_no || null);

            // ✅ FIX: PO DATE (MR → SO)
            frm.set_value("po_date", mr.custom_customer_po_date || null);

            frm.set_value("customer_address",      mr.custom_customer_address || null);
            frm.set_value("contact_person",        mr.custom_contact_person || null);
            frm.set_value("billing_address_gstin", mr.custom_billing_address_gstin || null);
            frm.set_value("gst_category",          mr.custom_gst_category || null);
            frm.set_value("place_of_supply",       mr.custom_place_of_supply || null);

            frm.set_value("shipping_address_name", mr.custom_shipping_address || null);
            if (mr.custom_shipping_address_display) {
                frm.set_value("shipping_address", mr.custom_shipping_address_display);
            }

            frm.set_value("custom_trade_type", mr.custom_trade_type || null);

            frm.set_value("company_address",        mr.custom_company_addresses_name || null);
            frm.set_value("company_contact_person", mr.custom_company_contact_person || null);
            frm.set_value("company_gstin",          mr.custom_company_gstin || null);
            if (mr.custom_company_address) {
                frm.set_value("company_address_display", mr.custom_company_address);
            }

            // -------------------------------
            // ITEMS
            // -------------------------------
            frm.clear_table("items");

            (mr.items || []).forEach(d => {
                let row = frm.add_child("items");
                row.item_code     = d.item_code;
                row.item_name     = d.item_name;
                row.description   = d.description;
                row.uom           = d.uom;
                row.qty           = d.qty;
                row.delivery_date = d.schedule_date;
                row.warehouse     = d.warehouse || d.target_warehouse;
                row.material_request = mr.name;
            });

            frm.refresh_field("items");
        }
    });
}





















