frappe.ui.form.on("Sales Order", {
    onload(frm) {
        // run only for new doc and when request no is empty
        if (!frm.is_new() || frm.doc.custom_request_no) return;

        const prev = frappe.get_prev_route();
        console.log("Prev route:", prev);

        // prev = [ "Form", "<Doctype>", "<Docname>" ]
        if (prev && prev.length >= 3) {
            const prev_doctype = prev[1];
            const prev_name = prev[2];

            // your Request doctype can be "Request" or "Material Request"
            if (["Request", "Material Request"].includes(prev_doctype) && prev_name) {
                frm.set_value("custom_request_no", prev_name);
                console.log("Set custom_request_no ->", prev_name);
            }
        }
    }
});

// Sales Order — Apply Freight (checkbox always editable)
const FREIGHT_ITEM_CODE   = "STO-ITEM-2025-00006";   // your Freight item
const ALLOW_FREIGHT_FIELD = "custom_apply_freight";

frappe.ui.form.on("Sales Order", {
  onload(frm) {
    frm.set_df_property(ALLOW_FREIGHT_FIELD, "read_only", 0);
    sync_freight_row(frm);
  },

  refresh(frm) {
    frm.set_df_property(ALLOW_FREIGHT_FIELD, "read_only", 0);
    sync_freight_row(frm);
  },

  [ALLOW_FREIGHT_FIELD](frm) {
    sync_freight_row(frm);
  }
});

/* ---------------- helpers ---------------- */

function sync_freight_row(frm) {
  const want = !!frm.doc[ALLOW_FREIGHT_FIELD];

  // remove empty rows first
  remove_empty_item_rows(frm);

  const has = has_freight_row(frm);

  if (want && !has) add_freight_row(frm);
  if (!want && has) remove_freight_rows(frm);
}

function add_freight_row(frm) {
  const row = frm.add_child("items");

  frappe.model.set_value(row.doctype, row.name, "item_code", FREIGHT_ITEM_CODE);
  frappe.model.set_value(row.doctype, row.name, "qty", 1);

  try {
    const dd = frm.doc.delivery_date || frappe.datetime.get_today();
    frappe.model.set_value(row.doctype, row.name, "delivery_date", dd);
  } catch {}

  frm.refresh_field("items");
  frm.script_manager?.trigger?.("calculate_taxes_and_totals");
}

// Remove rows where item_code is empty or null
function remove_empty_item_rows(frm) {
  frm.doc.items = (frm.doc.items || []).filter(d => {
    return (d.item_code || "").trim() !== "";
  });
  frm.refresh_field("items");
  // recalc totals since we removed rows
  frm.script_manager?.trigger?.("calculate_taxes_and_totals");
}

function remove_freight_rows(frm) {
  frm.doc.items = (frm.doc.items || []).filter(
    d => (d.item_code || "").trim().toLowerCase() !== FREIGHT_ITEM_CODE.toLowerCase()
  );
  frm.refresh_field("items");
  // recalc totals after removing freight rows
  frm.script_manager?.trigger?.("calculate_taxes_and_totals");
}

function has_freight_row(frm) {
  return (frm.doc.items || []).some(
    d => (d.item_code || "").trim().toLowerCase() === FREIGHT_ITEM_CODE.toLowerCase()
  );
}

