frappe.ui.form.on('Quotation', {
    refresh(frm) {

        frm.page.wrapper.find('button:contains("Make Material Request")').hide();
        $(frm.wrapper).find('.btn-request-indent').remove();

        if (!frm.doc.__islocal && (frm.doc.docstatus === 0 || frm.doc.docstatus === 1)) {

            frm.add_custom_button(__('Request (Indent)'), function() {

                frappe.call({
                    method: 'create_material_request_from_quotation',
                    args: { quotation: frm.doc.name },
                    freeze: true,
                    freeze_message: __('Preparing Material Request...'),
                    callback: function(r) {
