                        }

                        // OPEN NEW UNSAVED FORM
                        let mr_doc = r.message;

                        frappe.model.with_doctype("Material Request", function() {
                            let new_doc = frappe.model.copy_doc(mr_doc);
                            frappe.set_route("Form", "Material Request", new_doc.name);
                        });
                    }
                });

            }, __('Create')).addClass('btn-primary btn-request-indent');
        }
    }
});

