frappe.ui.form.on('Quotation', {
    refresh(frm) {

        // Hide standard "Make" buttons
        frm.page.wrapper
            .find('button:contains("Make Material Request")')
            .hide();

        frm.page.wrapper
            .find('button:contains("Sales Order")')
            .hide();

        // Remove old custom buttons (avoid duplicates)
        $(frm.wrapper).find('.btn-request-indent').remove();
        $(frm.wrapper).find('.btn-make-order-acceptance').remove();

        if (!frm.doc.__islocal && (frm.doc.docstatus === 0 || frm.doc.docstatus === 1)) {

            // 1) Material Request button (unchanged)
            frm.add_custom_button(__('Request (Indent)'), () => {

                frappe.call({
                    method: 'create_material_request_from_quotation',
                    args: { quotation: frm.doc.name },
                    freeze: true,
                    freeze_message: __('Preparing Material Request...'),
                    callback: function (r) {
                        if (r.exc || !r.message) {
                            frappe.msgprint(__('Error creating Material Request'));
                            return;
                        }

                        const mr_doc = r.message;

                        frappe.model.with_doctype('Material Request', () => {
                            const new_doc = frappe.model.copy_doc(mr_doc);
                            frappe.set_route('Form', 'Material Request', new_doc.name);
                        });
                    }
                });

            }, __('Create')).addClass('btn-primary btn-request-indent');


            // 2) "Order Acceptance" -> actually Sales Order
            frm.add_custom_button(__('Order Acceptance'), () => {

                frappe.call({
                    method: 'create_sales_order_from_quotation',
                    args: { quotation: frm.doc.name },
                    freeze: true,
                    freeze_message: __('Preparing Sales Order...'),
                    callback: function (r) {
                        if (r.exc || !r.message) {
                            frappe.msgprint(__('Error creating Sales Order'));
                            return;
                        }

                        const so_doc = r.message;

                        frappe.model.with_doctype('Sales Order', () => {
                            const new_doc = frappe.model.copy_doc(so_doc);
                            frappe.set_route('Form', 'Sales Order', new_doc.name);
                        });
                    }
                });

            }, __('Create')).addClass('btn-make-order-acceptance');
        }
    }
});

frappe.ui.form.on('Quotation Item', {
    // fires when an item is selected/changed in a child row
    item_code: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (!row.item_code) return;

        // fetch the custom field from Item doctype
        frappe.db.get_value('Item', row.item_code, 'custom_catalog_no')
            .then(r => {
                if (r && r.message && r.message.custom_catalog_no) {
                    frappe.model.set_value(cdt, cdn, 'custom_catalog_no', r.message.custom_catalog_no);
                } else {
                    // clear if not present
                    frappe.model.set_value(cdt, cdn, 'custom_catalog_no', '');
                }
            });
    },

});

frappe.ui.form.on('Sales Order', {
    onload(frm) {
        // 1) Check if we came from a Material Request
        const prev = frappe.get_prev_route();
        if (!prev || prev[1] !== "Material Request" || !prev[2]) {
            return;
        }

        const mr_name = prev[2];
        console.log("Prev route:", prev);
        console.log("Material Request:", mr_name);

        // 2) Set Request field on all rows (material_request)
        (frm.doc.items || []).forEach(row => {
            if (!row.material_request) {
                row.material_request = mr_name;
            }
        });
        frm.refresh_field("items");

        // 3) Fetch full MR doc from backend (standard API, no custom path)
        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Material Request",
                name: mr_name
            },
            callback(r) {
                if (!r.message) return;

                const mr = r.message;
                const mr_items = mr.items || [];

                // 4) Map MR item row-id -> SO item.material_request_item
                //    Here we map by item_code (you can change to idx if you prefer)
                mr_items.forEach(mr_row => {
                    const so_row = (frm.doc.items || []).find(
                        d => d.item_code === mr_row.item_code && !d.material_request_item
                    );

                    if (so_row) {
                        so_row.material_request_item = mr_row.name;  // <-- row id like 5btohcir8d
                    }
                });

                frm.refresh_field("items");
                console.log("Mapped MR item row_ids to SO:", mr_items);
            }
        });
    }
});

const set = (frm, f, v) => {
    console.log("Checking field:", f);
    if (frm.fields_dict[f]) {
        console.log("Field exists, setting value:", v);
        frm.set_value(f, v);
    } else {
        console.log("Field does not exist:", f);
    }
};

const call = (method, args, cb) =>
    frappe.call({ method, args, callback: cb });

const addr = (n, cb) =>
    call(
        "frappe.client.get",
        { doctype: "Address", name: n },
        r => r.message && cb(r.message)
    );

const fmt = (a) =>
    [
        a.address_line1,
        a.address_line2,
        a.city,
        `${a.state}${a.pincode ? " - " + a.pincode : ""}`,
        a.country
    ]
        .filter(Boolean)
        .join(", ");

frappe.ui.form.on("Material Request", {
    custom_customer_name(frm) {
        console.log("Available fields:", Object.keys(frm.fields_dict));
        if (!frm.doc.custom_customer_name) return;

        call(
            "frappe.client.get",
            { doctype: "Customer", name: frm.doc.custom_customer_name },
            r => {
                if (!r.message) return;

                const pa = r.message.customer_primary_address;
                set(frm, "custom_customer_address", pa);

                if (pa) {
                    addr(pa, a => {
                        set(frm, "custom_address_display", fmt(a));
                        set(frm, "custom_billing_address_gstin", a.gstin || "");
                        set(frm, "custom_gst_category", a.gst_category || "");
                        set(frm, "custom_place_of_supply", a.state || "");
                    });
                }

                // ===============================
                // FETCH CONTACT DETAILS (SAFE)
                // ===============================
                const contactName = r.message.customer_primary_contact;

                if (!contactName) {
                    console.log("⚠️ No primary contact for customer");
                } else {
                    call(
                        "frappe.client.get",
                        { doctype: "Contact", name: contactName },
                        res => {
                            if (!res.message) {
                                console.log("❌ Contact not found:", contactName);
                                return;
                            }

                            const phone =
                                (res.message.phone_nos &&
                                    res.message.phone_nos.length)
                                    ? res.message.phone_nos[0].phone
                                    : res.message.mobile_no || "";

                            console.log(
                                "Contact Name:",
                                contactName,
                                "Phone:",
                                phone
                            );

                            // Disable read-only on mobile field (safe)
                            if (frm.fields_dict.custom_mobile_no) {
                                frm.fields_dict.custom_mobile_no.df.read_only = 0;
                            }

                            // Set values
                            frm.doc.custom_contact_person = contactName;
                            frm.doc.custom_mobile_no = phone;

                            frm.refresh_field("custom_contact_person");
                            frm.refresh_field("custom_mobile_no");

                            console.log(
                                "Contact Person:",
                                frm.doc.custom_contact_person,
                                "Mobile:",
                                frm.doc.custom_mobile_no
                            );
                        }
                    );
                }

                // ===============================
                // FETCH SHIPPING ADDRESS
                // ===============================
                call(
                    "frappe.client.get_list",
                    {
                        doctype: "Address",
                        filters: [
                            ["Dynamic Link", "link_doctype", "=", "Customer"],
                            ["Dynamic Link", "link_name", "=", frm.doc.custom_customer_name],
                            ["Address", "is_shipping_address", "=", 1]
                        ],
                        fields: [
                            "name",
                            "address_line1",
                            "address_line2",
                            "city",
                            "state",
                            "pincode",
                            "country"
                        ],
                        limit_page_length: 1
                    },
                    r => {
                        if (r.message?.length) {
                            const a = r.message[0];
                            set(frm, "custom_shipping_address", a.name);
                            set(frm, "custom_shipping_addresses", fmt(a));
                            frm.refresh_field("custom_shipping_addresses");
                        } else if (pa) {
                            addr(pa, a => {
                                set(frm, "custom_shipping_address", a.name);
                                set(frm, "custom_shipping_addresses", fmt(a));
                                frm.refresh_field("custom_shipping_addresses");
                            });
                        }
                    }
                );
            }
        );
    },

    company(frm) {
        if (!frm.doc.company) return;

        const compAddr = isPrimary =>
            call(
                "frappe.client.get_list",
                {
                    doctype: "Address",
                    filters: isPrimary
                        ? [
                              ["Dynamic Link", "link_doctype", "=", "Company"],
                              ["Dynamic Link", "link_name", "=", frm.doc.company],
                              ["Address", "is_primary_address", "=", 1]
                          ]
                        : [
                              ["Dynamic Link", "link_doctype", "=", "Company"],
                              ["Dynamic Link", "link_name", "=", frm.doc.company]
                          ],
                    fields: [
                        "name",
                        "gstin",
                        "address_line1",
                        "address_line2",
                        "city",
                        "state",
                        "pincode",
                        "country"
                    ],
                    limit_page_length: 1
                },
                r => {
                    if (r.message?.length) {
                        const a = r.message[0];
                        set(frm, "custom_company_addresses_name", a.name);
                        set(frm, "custom_company_address", fmt(a));
                        set(frm, "custom_company_gstin", a.gstin || "");
                        frm.refresh_field("custom_company_address");
                    } else if (isPrimary) {
                        compAddr(false);
                    }
                }
            );

        compAddr(true);

        call(
            "frappe.client.get",
            { doctype: "Company", name: frm.doc.company },
            r => {
                if (r.message?.default_contact) {
                    call(
                        "frappe.client.get",
                        {
                            doctype: "Contact",
                            name: r.message.default_contact
                        },
                        res => {
                            if (res.message) {
                                const personName =
                                    res.message.contact_person ||
                                    res.message.full_name ||
                                    res.message.name;
                                set(frm, "custom_company_contact_person", personName);
                            }
                        }
                    );
                }
            }
        );
    }
});






























