function set_ip_description(frm) {
    if (frm.doc.material_request_type !== "Manufacture") {
        frm.set_value('custom_description', '');
        return;
    }

    const ip_map = {
        "0": "No dust protected, No water protected, sealent not necessary",

        "20": "Open hole or gap up to Ø12.5-mm accepted, No water protected, sealent not necessary",

        "21": "Open hole or gap up to Ø12.5-mm accepted, Dripping water should not enter, Seal all gaps by silicon sealent, use gasket for doors & covers",

        "24": "Protected against solid objects of 12.5mm diameter and greater",

        "31": "Protected against solid objects of 12.5mm diameter and greater",

        "41": "Open hole or gap up to Ø2.5-mm accepted, Dripping water should not enter, Seal all gaps by silicon sealent, use gasket for doors & covers",

        "42": "Open hole or gap up to Ø1.0-mm accepted, Dripping water should not enter, Seal all gaps by silicon sealent, use gasket for doors & covers",

        "44": "Open hole or gap up to Ø1.0-mm accepted, 15° Dripping water should not enter, Seal all gaps by silicon sealent, use gasket for doors & covers",

        "51": "Protected against solid objects of 1.0mm diameter and greater",

        "54": "Dust protected, No any hole or gap accepted, Dripping water should not enter, Seal all gaps by silicon sealent, use gasket for doors & covers",

        "55": "Dust protected, No any hole or gap accepted, Splashed water from any direction should not enter, Seal all gaps by silicon sealent, use gasket for doors & covers",

        "56": "Dust protected, Protected against water jet from any direction, Seal all gaps by silicon sealent, use gasket for doors & covers",

        "65": "Dust protected, No any hole or gap accepted, powerfull jet water from any direction should not enter, Seal all gaps by silicon sealent, use gasket for doors & covers",

        "66": "Dust protected, No any hole or gap accepted, Dust should not enter, Jet water from any direction should not enter, Seal all gaps by silicon sealent, use gasket for doors & covers",

        "IECEX Zone-1": "Protected in Hazardous area against explosive gases & liquid, explosion proof panel, Use silicon gasket for sealing, No any gap's accepted",

        "NIMA-4": "Dust protected, No any hole or gap accepted, Dust should not enter, powerfull Jet water from any direction should not enter, Seal all gaps by silicon sealent, use gasket for doors & covers"
    };

    const ip_class = frm.doc.custom_ip_class;

    if (ip_class && ip_map[ip_class]) {
        frm.set_value('custom_description', ip_map[ip_class]);
    } else {
        frm.set_value('custom_description', '');
    }
}

frappe.ui.form.on('Sales Order', {
    refresh(frm) {
        if (frm.doc.docstatus !== 1) return;

        const trade_type = frm.doc.custom_trade_type;

        // 1) Hide unwanted options (same for all trade types)
        const remove_common = [
            "Pick List",
            "Work Order",
            "Request",
            "Request for Raw Materials",
            "Purchase Order",
            "Project",
            "Payment Request",
            // "Payment"
        ];

        setTimeout(() => {
            remove_common.forEach(lbl => {
                frm.page.remove_inner_button(__(lbl), __("Create"));
