            // 2) Trade-type specific logic
            if (trade_type === "Domestic") {
                // Domestic: no Tax Invoice
                frm.page.remove_inner_button(__("Tax Invoice"), __("Create"));
            } else if (trade_type === "Export") {
                // Export: ensure order = Tax Invoice, Delivery Challan
