function open_customer_quotation_popup(frm) {

    if (!frm.doc.custom_customer_name) {
        frappe.msgprint("Please select Customer in Material Request first");
        return;
    }

    let dialog = new frappe.ui.Dialog({
        title: "Customer Quotations",
        size: "large",
        fields: [
            {
                fieldname: "customer",
                fieldtype: "Data",
                label: "Customer",
                read_only: 1
            },
            {
                fieldname: "quotation_table",
                fieldtype: "Table",
                label: "Quotations",
                cannot_add_rows: true,
                in_place_edit: false,
                fields: [
                    {
                        fieldname: "quotation",
                        fieldtype: "Link",
                        options: "Quotation",
                        label: "Quotation No",
                        in_list_view: 1,
                        read_only: 1
                    },
                    {
                        fieldname: "transaction_date",
                        fieldtype: "Date",
                        label: "Date",
                        in_list_view: 1,
                        read_only: 1
                    },
                    {
                        fieldname: "status",
                        fieldtype: "Data",
                        label: "Status",
                        in_list_view: 1,
                        read_only: 1
                    }
                ]
            }
        ],
        primary_action_label: "Add Items",
        primary_action() {

            let grid = dialog.get_field("quotation_table").grid;
            let selected = grid.get_selected_children();

            if (!selected.length) {
                frappe.msgprint("Please select at least one quotation");
                return;
            }

            get_items_from_selected_quotations(frm, selected.map(d => d.quotation));
            dialog.hide();
        }
    });

    dialog.show();
    dialog.set_value("customer", frm.doc.custom_customer_name);

    load_customer_quotations(frm, dialog);
}

function load_customer_quotations(frm, dialog) {

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Quotation",
            filters: [
                ["customer_name", "=", frm.doc.custom_customer_name],
                ["docstatus", "!=", 2]
            ],
            fields: [
                "name",
                "transaction_date",
                "status"
            ],
            order_by: "transaction_date desc"
        },
        callback: function (r) {

            let table = dialog.get_field("quotation_table");
            table.df.data = [];

            if (r.message && r.message.length) {
                r.message.forEach(q => {
                    table.df.data.push({
                        quotation: q.name,
                        transaction_date: q.transaction_date,
                        status: q.status
                    });
                });
            }

            table.grid.refresh();
        }
    });
}

function get_items_from_selected_quotations(frm, quotations) {

    // Clear existing items
    frm.clear_table("items");

    quotations.forEach(quotation => {

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Quotation",
                name: quotation
            },
            callback: function (r) {

                if (!r.message || !r.message.items) return;

                r.message.items.forEach(q_item => {

                    let row = frm.add_child("items");

                    // Basic item details
                    row.item_code = q_item.item_code;
                    row.item_name = q_item.item_name;
                    row.qty = q_item.qty;
                    row.uom = q_item.uom;

                    // ✅ Required By
                    row.required_by = q_item.schedule_date;

                    // ✅ Rate and amount fields (confirmed)
                    row.rate = q_item.rate;
                    row.amount = q_item.amount;

                    row.base_rate = q_item.base_rate;
                    row.base_amount = q_item.base_amount;

                    row.net_rate = q_item.net_rate;
                    row.net_amount = q_item.net_amount;

                    // Custom fields
                    row.custom_w = q_item.custom_w;
                    row.custom_d = q_item.custom_d;
                    row.custom_h = q_item.custom_h;
                    row.custom_t = q_item.custom_t;
                    row.custom_materials = q_item.custom_materials;
                });

                frm.refresh_field("items");
            }
        });

    });
}

