frappe.ui.form.on("Material Request", {
    custom_customer_name(frm) {
        if (!frm.doc.custom_customer_name) return;

        // Do not override if already set
        if (frm.doc.tc_name && frm.doc.custom_trade_type) return;

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Quotation",
                filters: {
                    party_name: frm.doc.custom_customer_name
                },
                fields: [
                    "tc_name",
                    "terms",
                    "custom_trade_type"   // ✅ fetch trade type
                ],
                order_by: "creation desc",
                limit_page_length: 1
            },
            callback(r) {
                if (!r.message || !r.message.length) return;

                const q = r.message[0];

                // ✅ Terms & Conditions
                if (q.tc_name && !frm.doc.tc_name) {
                    frm.set_value("tc_name", q.tc_name);
                }

                if (q.terms) {
                    frm.set_value("terms", q.terms);
                }

                // ✅ Trade Type
                if (q.custom_trade_type) {
                    frm.set_value("custom_trade_type", q.custom_trade_type);
                }

                frm.refresh_field("tc_name");
                frm.refresh_field("terms");
                frm.refresh_field("custom_trade_type");
            }
        });
    }
});

frappe.ui.form.on("Material Request", {
    custom_customer_name(frm) {
        if (!frm.doc.custom_customer_name) return;

        // do not override if already fetched
        if (frm.doc.custom_payment_tearm_template) return;

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Quotation",
                filters: {
                    party_name: frm.doc.custom_customer_name
                },
                fields: ["name", "payment_terms_template"],
                order_by: "creation desc",
                limit_page_length: 1
            },
            callback(r) {
                if (!r.message || !r.message.length) return;

                const quotation = r.message[0];

                // set payment term template
                if (quotation.payment_terms_template) {
                    frm.set_value(
                        "custom_payment_tearm_template",
                        quotation.payment_terms_template
                    );

                    // fetch payment schedule rows
                    fetch_payment_schedule_from_quotation(
                        frm,
                        quotation.name
                    );
                }
            }
        });
    }
});

function fetch_payment_schedule_from_quotation(frm, quotation_name) {
    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Quotation",
            name: quotation_name
        },
        callback(r) {
            if (!r.message || !r.message.payment_schedule) return;

            frm.clear_table("custom_payment_schedule");

            r.message.payment_schedule.forEach(row => {
                let child = frm.add_child("custom_payment_schedule");

                child.payment_term = row.payment_term;
                child.description = row.description;
                child.due_date = row.due_date;
                child.invoice_portion = row.invoice_portion;
                child.payment_amount = row.payment_amount;
            });

            frm.refresh_field("custom_payment_schedule");
        }
    });
}

