    }
});


function open_accessories_dialog(frm) {

    let filter_values = {};

    let d = new frappe.ui.Dialog({
        title: 'Add Accessories',
        size: 'large',

        fields: [
            {
                fieldname: 'accessory_type',
                label: 'Accessory Type',
                fieldtype: 'Link',
                options: 'Accessories Type',
                reqd: 1,
                onchange() {
                    load_accessories(d, filter_values);
                }
            },
{
    fieldname: 'item',
    label: 'Item',
    fieldtype: 'Link',
    options: 'Item',
    get_query: () => {
        return {
            filters: [
                ['Item', 'item_group', 'descendants of', 'Products'],
                ['Item', 'disabled', '!=', 1]
            ]
        };
    },
    onchange() {

                    let item_code = d.get_value('item');

                    if (!item_code) {
                        filter_values = {};
                        d.fields_dict.filter_info.$wrapper.html(`
                            <div style="padding:10px;background:#f0f0f0;border-radius:4px;">
                                <strong>Filters:</strong> Select Accessory Type
                            </div>
                        `);
                        return;
                    }

                    frappe.db.get_doc('Item', item_code).then(doc => {

                        filter_values = {
                            width: doc.custom_w ? [doc.custom_w] : [],
                            depth: doc.custom_d ? [doc.custom_d] : [],
                            height: doc.custom_h ? [doc.custom_h] : [],
                            thickness: doc.custom_t ? [doc.custom_t] : [],
                            material: doc.custom_material ? [doc.custom_material] : [],
                            design: doc.custom_design ? [doc.custom_design] : []
                        };

                        d.fields_dict.filter_info.$wrapper.html(
                            get_filter_info_html(filter_values, d.get_value('accessory_type'))
                        );

                        load_accessories(d, filter_values);
                    });
                }
            },

            {
                fieldname: 'filter_info',
                fieldtype: 'HTML',
                options: `
                    <div style="padding:10px;background:#f0f0f0;border-radius:4px;margin-bottom:10px;">
                        <strong>Filters:</strong> Select Accessory Type
                    </div>
                `
            },
            {
                fieldname: 'accessories_html',
                fieldtype: 'HTML',
                options: '<div id="accessories-table-container"></div>'
            }
        ],

        primary_action_label: 'Add',

        primary_action() {

            let v = d.get_values();

            if (!v.accessory_type) {
                frappe.msgprint('Please select Accessory Type');
                return;
            }

            let selected_items = [];

            d.$wrapper.find('input.accessory-check:checked').each(function () {

                let row = $(this).closest('tr');

                let item_code = row.find('.item-code').text().trim();
                let item_name = row.find('.item-name').text().trim();

                selected_items.push({
                    item_code,
                    item_name
                });
            });

            if (!selected_items.length) {
                frappe.msgprint('Please select at least one accessory');
                return;
            }

            selected_items.forEach(item => {

                let child = frm.add_child('items');

                child.item_code = item.item_code;
                child.item_name = item.item_name;
                child.qty = 1;
            });

            frm.refresh_field('items');
            d.hide();
        }
    });


    function load_accessories(dialog, filter_values) {

        let v = dialog.get_values();

        if (!v || !v.accessory_type) {
            return;
        }

        let filters = {
            item_group: 'Accessories',
            custom_accessories_type: v.accessory_type
        };

        if (v.item && v.accessory_type !== 'General') {

            if (filter_values.width?.length)
                filters.custom_w = filter_values.width[0];

            if (filter_values.depth?.length)
                filters.custom_d = filter_values.depth[0];

            if (filter_values.height?.length)
                filters.custom_h = filter_values.height[0];

            if (filter_values.thickness?.length)
                filters.custom_t = filter_values.thickness[0];

            if (filter_values.material?.length)
                filters.custom_material = filter_values.material[0];

            if (filter_values.design?.length)
                filters.custom_design = filter_values.design[0];
        }

        dialog.fields_dict.filter_info.$wrapper.html(
            get_filter_info_html(filter_values, v.accessory_type)
        );

        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Item',
                filters: filters,
                fields: ['name', 'item_name'],
                limit_page_length: 50
            },
            callback(r) {

                let container = dialog.$wrapper.find('#accessories-table-container');

                if (!r.message || !r.message.length) {
                    container.html('<p style="padding:10px;color:#999;">No accessories found</p>');
                    return;
                }

                let html = `
                    <table class="table table-bordered">
                        <thead>
                            <tr>
                                <th>Select</th>
                                <th>Item Code</th>
                                <th>Item Name</th>
                            </tr>
                        </thead>
                        <tbody>
                `;

                r.message.forEach(item => {
                    html += `
                        <tr>
                            <td><input type="checkbox" class="accessory-check"></td>
                            <td class="item-code">${item.name}</td>
                            <td class="item-name">${item.item_name || ''}</td>
                        </tr>
                    `;
                });

                html += '</tbody></table>';

                container.html(html);
            }
        });
    }

    d.show();
}


function get_filter_info_html(filter_values, accessory_type) {

    let filter_items = [];

    if (accessory_type) {
        filter_items.push(`Accessory Type: ${accessory_type}`);
    }

    if (filter_values.width?.length)
        filter_items.push(`Width: ${filter_values.width.join(', ')}`);

    if (filter_values.depth?.length)
        filter_items.push(`Depth: ${filter_values.depth.join(', ')}`);

    if (filter_values.height?.length)
        filter_items.push(`Height: ${filter_values.height.join(', ')}`);

    if (filter_values.thickness?.length)
        filter_items.push(`Thickness: ${filter_values.thickness.join(', ')}`);

    if (filter_values.material?.length)
        filter_items.push(`Material: ${filter_values.material.join(', ')}`);

    if (filter_values.design?.length)
        filter_items.push(`Design: ${filter_values.design.join(', ')}`);

    if (!filter_items.length) {
        return `
            <div style="padding:10px;background:#f0f0f0;border-radius:4px;margin-bottom:10px;">
                <strong>Filters:</strong> Select Accessory Type
            </div>
        `;
    }

    return `
        <div style="padding:10px;background:#e8f4f8;border-radius:4px;margin-bottom:10px;">
            <strong>Applied Filters:</strong> ${filter_items.join(' | ')}
        </div>
    `;
}






























































