    if (!frm.doc.item_group) return; // Stop if no item group selected

    // Fetch the Parent Item Group of selected Item Group
    frappe.db.get_value('Item Group', frm.doc.item_group, 'parent_item_group', function(r) {

        if (!r || !r.parent_item_group) return;

        let parent_group = r.parent_item_group;

        // Condition 1: Parent Item Group = Products
        if (parent_group === 'Products') {
            frm.set_value('is_stock_item', 1);                 // ✅ Maintain Stock - CHECKED
            frm.set_value('is_sales_item', 1);                 // ✅ Allow Sales - CHECKED
            frm.set_value('include_item_in_manufacturing', 1); // ✅ Include Item In Manufacturing - CHECKED
            frm.set_value('is_purchase_item', 0);              // ☐ Allow Purchase - UNCHECKED
        }

        // Condition 2: Parent Item Group = Assembly Item
else if (parent_group === 'Assembly Item') {

    // Keep Maintain Stock checked for these Item Groups
    if (["Standard Item", "Specialised Item"].includes(frm.doc.item_group)) {
        frm.set_value('is_stock_item', 1);
    } else {
        frm.set_value('is_stock_item', 0);
    }

    frm.set_value('is_sales_item', 0);
    frm.set_value('is_purchase_item', 0);
    frm.set_value('include_item_in_manufacturing', 0);
}

        // Condition 3: Parent Item Group = All Item Groups
        else if (parent_group === 'All Item Groups') {
            frm.set_value('is_stock_item', 0);                 // ☐ Maintain Stock - UNCHECKED
        }

    });
}

