// ────────────────────CORRECT STOCK ENTRIES EXCEPT JOBWORK GRN─────────────────────────
// PURCHASE ORDER — CLIENT SCRIPT (OPTIMISED)
// ─────────────────────────────────────────────
//
// KEY CHANGES vs original:
//  1. All refresh-time server calls run in PARALLEL (Promise.all).
//  2. Results cached on `frm._jwCache`; no duplicate fetches.
//  3. Refresh debounced to avoid storm-firing on rapid form events.
//
// BUG FIX — Scrap GRN "Not Permitted" error:
//  The original trigger_scrap_grn() used frappe.client.get_list for
//  Stock Entry / Stock Entry Detail / Warehouse — all of which require
//  explicit read permissions on those doctypes.  Users with restricted
//  roles get "Not permitted" dialogs.
//
//  Fix: replace ALL those frappe.client.get_list calls in trigger_scrap_grn
//  with a SINGLE call to the server-side API script `get_scrap_grn_data`
//  which runs every query with ignore_permissions=True and returns a
//  clean payload: { scrap_warehouse, scrapped_rm_rows, scrapped_fg_rows,
//                   grn_rm_rows, grn_fg_rows }.
//  Only `get_transferred_qty` (already server-side) is kept as a second
//  parallel call — it was never the source of the permission errors.
// ─────────────────────────────────────────────

// ── Debounce helper ──────────────────────────
function _debounce(fn, ms) {
    let t;
    return function(...args) { clearTimeout(t); t = setTimeout(() => fn.apply(this, args), ms); };
}

// ── Promise wrapper around frappe.call ───────
function _fc(method, args) {
    return new Promise((resolve, reject) =>
        frappe.call({
            method,
            args,
            callback : r  => resolve(r.message),
            error    : () => reject(new Error(method + ' failed'))
        })
    );
}

// ── Open created Stock Entry in a new form tab ─
function _open_stock_entry(r, error_title) {
    if (r && r.message && r.message.name) {
        frappe.set_route('Form', 'Stock Entry', r.message.name);
    } else {
        frappe.msgprint({
            title    : error_title || 'Failed',
            message  : 'Stock Entry could not be created. Check Error Log.',
            indicator: 'red'
        });
    }
}

