// ─── 1. Item Filter ───────────────────────────
function setup_item_filter(frm) {
    frm.fields_dict['items'].grid.get_field('item_code').get_query = function() {
        return {
            filters: [
                ['Item', 'disabled'        , '=', 0],
                ['Item', 'is_purchase_item', '=', 1]
            ]
        };
    };
}

// ─── 2. Transfer Button ───────────────────────
function handle_transfer_button(frm, transferred_map) {
    let btn_wrapper = frm.fields_dict['custom_make_stock_transfer_entry'];
    if (!btn_wrapper) return;

    let $btn = $(btn_wrapper.wrapper).find('button')
        .removeClass('btn-default btn-primary')
        .addClass('btn-danger');

    let raw_materials = frm.doc.suppiler_materials || [];

    if (!raw_materials.length) { $btn.hide(); return; }

    if (frm.doc.docstatus !== 1) {
        $btn.prop('disabled', true).css('opacity', '0.5').show();
        return;
    }

    let has_pending = raw_materials.some(mat =>
        (parseFloat(mat.qty || 0) - (transferred_map[mat.item_code] || 0)) > 0
    );

    if (!has_pending) { $btn.hide(); return; }

    $btn.prop('disabled', false).css('opacity', '1').show()
        .off('click').on('click', () => trigger_stock_transfer(frm, transferred_map));
}

// ─── 3. Stock Transfer Handler ────────────────
function trigger_stock_transfer(frm, transferred_map) {
    let raw_materials = frm.doc.suppiler_materials || [];
    transferred_map   = transferred_map || {};

    let pending_items = raw_materials
        .map(mat => Object.assign({}, mat, {
            pending_qty: parseFloat(mat.qty || 0) - (transferred_map[mat.item_code] || 0)
        }))
        .filter(mat => mat.pending_qty > 0);

    if (!pending_items.length) {
        frappe.msgprint({ title: 'Transfer Complete', message: 'All items have already been transferred.', indicator: 'blue' });
        return;
    }
    if (!frm.doc.custom_raw_material_warehouse_) {
        frappe.msgprint({ title: 'Missing Warehouse', message: 'Please set Raw Material Warehouse.', indicator: 'red' });
        return;
    }
    if (!frm.doc.custom_jobworker__warehouse_) {
        frappe.msgprint({ title: 'Missing Warehouse', message: 'Please set JobWorker Warehouse.', indicator: 'red' });
        return;
    }

    let selected = pending_items.map(mat => ({
        row_name : mat.name,
        item_code: mat.item_code,
        item_name: mat.item_name,
        qty      : mat.pending_qty,
        uom      : mat.uom
    }));

    frappe.call({
        method  : 'make_stock_transfer_entry',
        args    : { purchase_order_name: frm.doc.name, selected_items: JSON.stringify(selected) },
        callback: r => _open_stock_entry(r, 'Transfer Failed'),
        error   : () => frappe.msgprint({ title: 'Transfer Failed', message: 'An error occurred. Check Error Log.', indicator: 'red' })
    });
}

// ─── 4. GRN Button ───────────────────────────
function handle_grn_button(frm, has_transfer, received_map) {
    let btn_wrapper = frm.fields_dict['custom_create_job_work_grn'];
    if (!btn_wrapper) return;

    let $btn = $(btn_wrapper.wrapper).find('button')
        .removeClass('btn-default btn-primary btn-danger')
        .addClass('btn-warning');

    let fg_target = frm.doc.job_work_grn || [];

    if (!has_transfer || !fg_target.length) { $btn.hide(); return; }

    let has_pending_fg = fg_target.some(fg =>
        (received_map[fg.item_code] || 0) < parseFloat(fg.qty || 0)
    );

    if (!has_pending_fg) {
        $btn.prop('disabled', true).css('opacity', '0.5').show();
        return;
    }

    $btn.prop('disabled', false).css('opacity', '1').show()
        .off('click').on('click', function () {

            // ── Single Server Script call — bypasses child doctype permission error ──
            frappe.call({
                method  : 'get_job_work_grn_status',   // matches Server Script name
                args    : { purchase_order_name: frm.doc.name },
                callback: function (r) {
                    let data         = r.message     || {};
                    let consumed_map = data.consumed_map || {};
                    let rcvd_map     = data.received_map || {};

                    trigger_job_work_grn(frm, consumed_map, rcvd_map);
                },
                error: function () {
                    frappe.msgprint({
                        title    : 'Error',
                        message  : 'Could not fetch GRN status. Check error log.',
                        indicator: 'red'
                    });
                }
            });
        });
}

// ─── 5. GRN Handler ───────────────────────────
function trigger_job_work_grn(frm, consumed_map, received_map) {
    let po_items = frm.doc.job_work_grn || [];
    let raw_materials_list = frm.doc.suppiler_materials || [];

    let transferred_map = frm._jwCache.transferred_map || {};

    if (!frm.doc.custom_raw_material_warehouse_) {
        frappe.msgprint({ title: 'Missing Warehouse', message: 'Please set Raw Material Warehouse on the PO.', indicator: 'red' });
        return;
    }

    // ── RM calculation = Total Transferred - Already Consumed ──
    // ── RM calculation = Total Transferred - Already Consumed ──
let raw_materials = raw_materials_list.map(mat => {
    let transferred = flt(transferred_map[mat.item_code]) || 0;
    let consumed = flt(consumed_map[mat.item_code]) || 0;
    let pending_qty = transferred - consumed;

    return {
        item_code: mat.item_code,
        item_name: mat.item_name,
        qty: pending_qty,
        uom: mat.uom,
        s_warehouse: frm.doc.custom_jobworker__warehouse_
    };
}).filter(r => r.qty > 0.001); // Use a small threshold for float precision

// ── FG calculation = Total PO Qty - Already Received ──
let finished_goods = po_items.map(r => {
    let po_qty = flt(r.qty) || 0;
    let received_qty = flt(received_map[r.item_code]) || 0;
    let pending_fg = po_qty - received_qty;

    return {
        item_code: r.item_code,
        item_name: r.item_name || '',
        qty: pending_fg,
        uom: r.uom
    };
}).filter(r => r.qty > 0.001);

// Logic Check: Allow entry if either RM or FG has pending balance
if (raw_materials.length === 0 && finished_goods.length === 0) {
    frappe.show_alert({
        message: __('All items have been fully processed for this Job Work.'),
        indicator: 'orange'
    }, 4);
    return;
}

// Proceed with frappe.call...

    frappe.call({
        method  : 'create_job_work_grn',
        args    : {
            purchase_order_name: frm.doc.name,
            raw_material_items : JSON.stringify(raw_materials),
            finished_items     : JSON.stringify(finished_goods),
            target_warehouse   : frm.doc.custom_raw_material_warehouse_
        },
        callback: r => _open_stock_entry(r, 'GRN Failed'),
        error   : () => frappe.msgprint({ title: 'GRN Failed', message: 'An error occurred. Check Error Log.', indicator: 'red' })
    });
}

// ─── 6. Scrap GRN Button ──────────────────────
// NOTE: frm.add_custom_button() is called on every refresh.
// Without removing the old button first, each refresh stacks a new click
// handler on top of the previous one — causing duplicate (and stale)
// `create_scrap_grn` calls.  Always remove before re-adding.
function handle_scrap_grn_button(frm, has_grn) {
    // Always remove any previously added button to prevent duplicate handlers
    frm.remove_custom_button(__('Scrap GRN'));

    if (!has_grn) return;

    let $btn = $(frm.add_custom_button(__('Scrap GRN'), () => trigger_scrap_grn(frm)));
    $btn.removeClass('btn-default btn-secondary').addClass('btn-success');
}

// ─── 7. Scrap GRN Handler ─────────────────────
// ─────────────────────────────────────────────────────────────────────────────
//  FIX: "Not permitted" error
//
//  Root cause  → frappe.client.get_list calls for Stock Entry, Stock Entry
//                Detail, and Warehouse all respect the logged-in user's role
//                permissions.  Restricted users see "Not permitted" dialogs.
//
//  Solution    → Replace every frappe.client.get_list call with a single call
//                to the server-side API script `get_scrap_grn_data`, which runs
//                all queries with ignore_permissions=True and returns one clean
//                payload.  Only `get_transferred_qty` (already a server method)
//                is kept as a parallel call — it was never the source of errors.
// ─────────────────────────────────────────────────────────────────────────────
function trigger_scrap_grn(frm) {
    if (!frm.doc.custom_jobworker__warehouse_) {
        frappe.msgprint({
            title: 'Missing Warehouse',
            message: 'Please set JobWorker Warehouse before creating Scrap GRN.',
            indicator: 'red'
        });
        return;
    }

    let raw_materials = frm.doc.suppiler_materials || [];
    let fg_items      = frm.doc.job_work_grn       || [];

    Promise.all([
        raw_materials.length
            ? _fc('get_transferred_qty', { purchase_order_name: frm.doc.name })
            : Promise.resolve({}),

        _fc('get_scrap_grn_data', {
            purchase_order_name: frm.doc.name,
            company: frm.doc.company
        }).catch(() => null)

    ]).then(function([transferred_map, scrap_data]) {

        if (!scrap_data) {
            frappe.msgprint({
                title: 'Scrap GRN Failed',
                message: 'Could not fetch scrap data.',
                indicator: 'red'
            });
            return;
        }

        let {
            scrap_warehouse,
            scrapped_rm_rows,
            scrapped_fg_rows,
            grn_rm_rows,
            grn_fg_rows
        } = scrap_data;

        if (!scrap_warehouse) {
            frappe.msgprint({
                title: 'Scrap Warehouse Not Found',
                message: 'Scrap warehouse not configured.',
                indicator: 'red'
            });
            return;
        }

        // Build maps
        let already_scrapped_rm_map = {};
        (scrapped_rm_rows || []).forEach(r => {
            already_scrapped_rm_map[r.item_code] =
                (already_scrapped_rm_map[r.item_code] || 0) + r.qty;
        });

        let already_scrapped_fg_map = {};
        (scrapped_fg_rows || []).forEach(r => {
            already_scrapped_fg_map[r.item_code] =
                (already_scrapped_fg_map[r.item_code] || 0) + r.qty;
        });

        let grn_rm_returned_map = {};
        (grn_rm_rows || []).forEach(r => {
            grn_rm_returned_map[r.item_code] =
                (grn_rm_returned_map[r.item_code] || 0) + r.qty;
        });

        let grn_fg_received_map = {};
        (grn_fg_rows || []).forEach(r => {
            grn_fg_received_map[r.item_code] =
                (grn_fg_received_map[r.item_code] || 0) + r.qty;
        });

        // ✅ PASS ALL MAPS (IMPORTANT FIX)
        _build_scrap_entry(
            frm,
            raw_materials,
            fg_items,
            grn_fg_received_map,
            transferred_map || {},
            already_scrapped_rm_map,
            already_scrapped_fg_map,
            grn_rm_returned_map,
            scrap_warehouse
        );

    });
}

// ── Builds the Scrap GRN stock entry ─────────────────────────────────
//
// Quantity logic (matches expected two-row entry):
//
//   RM row  → qty = total_transferred − already_scrapped
//             GRN returns are intentionally NOT subtracted here.
//             The Scrap GRN moves all RM that was ever sent to the
//             jobworker out to scrap, regardless of partial GRN returns.
//
//   FG row  → qty = total_po_qty − already_scrapped
//             GRN received qty is intentionally NOT subtracted here.
//             All ordered FG is directed to scrap through this entry.
//
//   The only deduction in both cases is `already_scrapped`, which
//   prevents the same qty from being scrapped twice if the button
//   is clicked again after a partial Scrap GRN was submitted.
//
function _build_scrap_entry(
    frm,
    raw_materials,
    fg_items,
    fg_received_map,
    transferred_map,
    already_scrapped_rm_map,
    already_scrapped_fg_map,
    grn_rm_returned_map,
    scrap_warehouse
) {

    let scrap_items = [];

    // ───────── RM (ROW 1) ─────────
    raw_materials.forEach(mat => {

        let sent     = transferred_map[mat.item_code] || 0;
        let returned = grn_rm_returned_map[mat.item_code] || 0;
        let scrapped = already_scrapped_rm_map[mat.item_code] || 0;

        let remaining = sent - returned - scrapped;

        if (remaining > 0) {
            scrap_items.push({
                item_code: mat.item_code,
                item_name: mat.item_name,
                qty: remaining,
                uom: mat.uom,

                item_type: "rm",

                // 🔥 FORCE UNIQUE ROW
                name: "rm_" + mat.name + "_" + frappe.utils.get_random(5)
            });
        }
    });

    // ───────── FG (ROW 2) ─────────
  // ✅ FINISHED GOOD (FG)
fg_items.forEach(fg => {

    let ordered  = parseFloat(fg.qty || 0);
    let received = fg_received_map[fg.item_code] || 0;
    let scrapped = already_scrapped_fg_map[fg.item_code] || 0;

    let remaining = ordered - received - scrapped;

    // 🔥 CHANGE THIS CONDITION
    if (remaining <= 0) {
        remaining = 0;  // force entry
    }

    // 🔥 ALWAYS PUSH FG ROW
    scrap_items.push({
        item_code: fg.item_code,
        item_name: fg.item_name || '',
        qty: remaining,
        uom: fg.uom,

        item_type: "fg"
    });

});

    if (!scrap_items.length) {
        frappe.msgprint({
            title: "No Scrap Pending",
            message: "All items already scrapped.",
            indicator: "blue"
        });
        return;
    }

    // 🔥 DEBUG (IMPORTANT)
    console.log("SCRAP ITEMS SENT →", scrap_items);

    frappe.call({
        method: "create_scrap_grn",
        args: {
            purchase_order_name: frm.doc.name,
            scrap_items: JSON.stringify(scrap_items),

            rm_s_warehouse: frm.doc.custom_raw_material_warehouse_,
            fg_s_warehouse: frm.doc.custom_jobworker__warehouse_,
            t_warehouse: scrap_warehouse
        },
        callback: r => _open_stock_entry(r, "Scrap GRN Failed")
    });
}























