frappe.ui.form.on('BOM', {
    onload: function(frm) {
        set_item_query(frm);
    },
    refresh: function(frm) {
        set_item_query(frm);
    },

    // when Finished Goods checkbox toggled
    custom_finished_goods: function(frm) {
        set_item_query(frm);
        maybe_clear_item_if_mismatch(frm);
    },

    // when Raw Material checkbox toggled
    custom_raw_material_: function(frm) {
        set_item_query(frm);
        maybe_clear_item_if_mismatch(frm);
    }
});

// helper: decide which filter to apply
function set_item_query(frm) {
    frm.set_query('item', function() {
        // precedence: custom_finished_goods over custom_raw_material_
        if (frm.doc.custom_finished_goods) {
            return { filters: { 'item_group': 'Finished Goods' } };
        } else if (frm.doc.custom_raw_material_) {
            return { filters: { 'item_group': 'Raw Material' } };
        } else {
            return {};
        }
    });

    // If you also use a different field name like item_code or production_item,
    // set that query too (example for item_code):
    frm.set_query('item_code', function() {
        if (frm.doc.custom_finished_goods) {
            return { filters: { 'item_group': 'Finished Goods' } };
        } else if (frm.doc.custom_raw_material_) {
            return { filters: { 'item_group': 'Raw Material' } };
        } else {
            return {};
        }
    });
}

// helper: clear the item if it doesn't match the current filter
function maybe_clear_item_if_mismatch(frm) {
    if (!frm.doc.item) return;

    // If no filter active, keep selected item
    if (!frm.doc.custom_finished_goods && !frm.doc.custom_raw_material_) return;

    frappe.db.get_value('Item', frm.doc.item, 'item_group')
        .then(r => {
            if (!r || !r.message) return;
            const current_group = r.message.item_group;
            const want_finished = !!frm.doc.custom_finished_goods;
            const want_raw = !!frm.doc.custom_raw_material_;

            // Determine valid group based on active checkboxes (finished takes precedence)
            let valid_group = null;
            if (want_finished) valid_group = 'Finished Goods';
            else if (want_raw) valid_group = 'Raw Material';

            if (valid_group && current_group !== valid_group) {
                frm.set_value('item', null);
                frm.refresh_field('item');
            }
        });
}

