// Remove the "Sales Order" entry from any open dropdown
function remove_sales_order_from_create() {
    const items = document.querySelectorAll(
        '.dropdown-menu .dropdown-item, .dropdown-menu [role="menuitem"], .dropdown-menu a'
    );

    items.forEach(el => {
        const text = (el.innerText || el.textContent || "").trim().toLowerCase();
        if (text === "sales order") {
            const li = el.closest("li") || el;
            li.remove();
        }
    });
}

// Watch for menu being rendered (React re-renders etc.)
function start_sales_order_menu_observer() {
    const observer = new MutationObserver(() => {
        remove_sales_order_from_create();
    });

    observer.observe(document.body, {
        childList: true,
        subtree: true,
    });

    window.__quotation_so_observer = observer;
}

