        cache_items(frm);
    },
    refresh: function(frm) {
        if (!frm._cached_items) cache_items(frm);
    }
});

function cache_items(frm) {
    frm._cached_items = (frm.doc.items || []).map(function(r) {
        return {
            name: r.name,
            item_code: r.item_code,
            item_name: r.item_name,
            description: r.description,
            uom: r.uom,
            qty: r.qty,
            target_warehouse: r.target_warehouse,
            schedule_date: r.schedule_date
        };
    });
}

frappe.ui.form.on('Request Item', {
    schedule_date: function(frm, cdt, cdn) {
        var row = locals[cdt][cdn];

        if (!frm._cached_items) {
            cache_items(frm);
        }

        var orig = (frm._cached_items || []).find(function(r) { return r.name === row.name; });
        if (!orig) {
            // rebuild cache and exit
            setTimeout(function() { cache_items(frm); }, 100);
            return;
        }

        var fields_to_preserve = [
            'item_code', 'item_name', 'description', 'uom',
            'qty', 'target_warehouse'
        ];

        fields_to_preserve.forEach(function(field) {
            var current = row[field];
            var original = orig[field];
            if ((current === undefined || current === null || current === '') &&
                (original !== undefined && original !== null && original !== '')) {
                frappe.model.set_value(cdt, cdn, field, original);
            }
        });

        var idx = (frm._cached_items || []).findIndex(function(r) { return r.name === row.name; });
        if (idx !== -1) {
            fields_to_preserve.forEach(function(f) {
                frm._cached_items[idx][f] = locals[cdt][cdn][f];
            });
            frm._cached_items[idx].schedule_date = row.schedule_date;
        }
    },

    items_add: function(frm) {
        setTimeout(function() { cache_items(frm); }, 150);
    },

    items_remove: function(frm) {
        setTimeout(function() { cache_items(frm); }, 150);
    }
});

