// 🔥 MAIN FUNCTION (OPTIMIZED + SAFE)
function open_price_dialog(item_codes, title) {

    // ✅ STEP 1: GET PRICE LISTS
    frappe.db.get_list('Price List', {
        fields: ['name'],
        limit: null
    }).then(price_lists => {

        let all_price_lists = price_lists.map(p => p.name);

        // ✅ STEP 2: GET EXISTING ITEM PRICES
        frappe.db.get_list('Item Price', {
            fields: ['name', 'item_code', 'price_list', 'price_list_rate'],
            filters: { item_code: ['IN', item_codes] },
            limit: null
        }).then(existing => {

            let data = [];

            // 🔁 CREATE MATRIX (Item × Price List)
            item_codes.forEach(item => {

                all_price_lists.forEach(pl => {

                    let found = existing.find(d =>
                        d.item_code === item && d.price_list === pl
                    );

                    if (found) {
                        data.push(found);
                    } else {
                        data.push({
                            item_code: item,
                            price_list: pl,
                            price_list_rate: 0,
                            __islocal: 1
                        });
                    }
                });
            });

            let d = new frappe.ui.Dialog({
                title: title,

                fields: [{
                    fieldname: 'prices_table',
                    fieldtype: 'Table',
                    label: 'Item Prices',
                    in_place_edit: 1,
                    cannot_add_rows: 1,
                    cannot_delete_rows: 1,
                    fields: [

                        { fieldname: 'name', fieldtype: 'Data', hidden: 1 },

                        {
                            label: 'Item',
                            fieldname: 'item_code',
                            fieldtype: 'Link',
                            options: 'Item',
                            in_list_view: 1,
                            read_only: 1
                        },

                        {
                            label: 'Price List',
                            fieldname: 'price_list',
                            fieldtype: 'Link',
                            options: 'Price List',
                            in_list_view: 1,
                            read_only: 1
                        },

                        {
                            label: 'Rate',
                            fieldname: 'price_list_rate',
                            fieldtype: 'Currency',
                            in_list_view: 1
                        }
                    ],
                    data: data
                }],

                size: 'extra-large',

                primary_action_label: 'Save',

                primary_action: function () {

                    let rows = d.get_values().prices_table;

                    if (!rows || !rows.length) {
                        frappe.msgprint("No data");
                        return;
                    }

                    let calls = [];

                    rows.forEach(row => {

                        // ✅ UPDATE (only real DB rows)
                        if (!row.__islocal && row.name) {
                            calls.push(
                                frappe.call({
                                    method: "frappe.client.set_value",
                                    args: {
                                        doctype: "Item Price",
                                        name: row.name,
                                        fieldname: "price_list_rate",
                                        value: row.price_list_rate
                                    }
                                })
                            );
                        }

                        // ✅ INSERT (skip zero)
                        else if (row.price_list_rate && row.price_list_rate !== 0) {
                            calls.push(
                                frappe.call({
                                    method: "frappe.client.insert",
                                    args: {
                                        doc: {
                                            doctype: "Item Price",
                                            item_code: row.item_code,
                                            price_list: row.price_list,
                                            price_list_rate: row.price_list_rate
                                        }
                                    }
                                })
                            );
                        }
                    });

                    Promise.all(calls).then(() => {
                        frappe.msgprint("Prices saved successfully");
                        d.hide();

                        // ✅ SAFE REFRESH (NO BUG)
                        frappe.show_alert({
                            message: "List refreshed",
                            indicator: "green"
                        });
                    });
                }
            });

            d.show();
        });
    });
}

