// Purchase Order — Client Script (XHR Redirect)
// Redirects XMLHttpRequest calls for Material Request Item
// to our custom server endpoint that filters at DB level

frappe.ui.form.on('Purchase Order', {
    setup: function(frm) {
        install_xhr_redirect();
    }
});

function install_xhr_redirect() {
    if (window.__po_xhr_redirect_v8) return;
    window.__po_xhr_redirect_v8 = true;

    var OrigXHR  = window.XMLHttpRequest;

    function PatchedXHR() {
        var xhr      = new OrigXHR();
        var _open    = xhr.open.bind(xhr);
        var _send    = xhr.send.bind(xhr);
        var captured_url  = '';
        var captured_body = '';
        var is_mr_call    = false;

        // Intercept open() to capture the URL
        xhr.open = function(method, url) {
            captured_url = url || '';

            // Detect the exact frappe.client.get_list call
            if (
                typeof captured_url === 'string'
                && captured_url.indexOf('frappe.client.get_list') !== -1
            ) {
                is_mr_call = true; // tentative — confirm in send()
            }
            return _open.apply(xhr, arguments);
        };

        // Intercept send() to inspect the body (doctype is in body)
        xhr.send = function(body) {
            if (is_mr_call) {
                var bodyStr = typeof body === 'string' ? body : '';
                var isMRItem = (
                    bodyStr.indexOf('Material%20Request%20Item') !== -1 ||
                    bodyStr.indexOf('Material+Request+Item')     !== -1 ||
                    bodyStr.indexOf('Material Request Item')     !== -1
                );

                if (isMRItem) {
                    console.log('[PO Filter v8] XHR intercepted — redirecting to pending endpoint');

                    // Build new request to our custom server script endpoint
                    var newXhr = new OrigXHR();
                    newXhr.open('POST', '/api/method/get_pending_mr_items', true);

                    // Copy all request headers
                    try {
                        var headers = xhr.__headers || {};
                        Object.keys(headers).forEach(function(k) {
                            newXhr.setRequestHeader(k, headers[k]);
                        });
                    } catch(e) {}

                    // Copy credentials/withCredentials
                    newXhr.withCredentials = xhr.withCredentials;

                    // Forward all event handlers from original XHR
                    ['onload','onreadystatechange','onerror','ontimeout'].forEach(function(ev) {
                        newXhr[ev] = xhr[ev];
                    });

                    // Override readyState/response proxying
                    Object.defineProperty(xhr, 'readyState',  { get: function() { return newXhr.readyState;  } });
                    Object.defineProperty(xhr, 'status',      { get: function() { return newXhr.status;      } });
                    Object.defineProperty(xhr, 'statusText',  { get: function() { return newXhr.statusText;  } });
                    Object.defineProperty(xhr, 'response',    { get: function() { return newXhr.response;    } });
                    Object.defineProperty(xhr, 'responseText',{ get: function() { return newXhr.responseText;} });

                    newXhr.send(body);
                    return; // Don't send original request
                }
            }

            // All other calls: pass through untouched
            return _send.apply(xhr, arguments);
        };

        // Track headers set on the original XHR so we can copy them
        var _setHeader = xhr.setRequestHeader.bind(xhr);
        xhr.__headers  = {};
        xhr.setRequestHeader = function(k, v) {
            xhr.__headers[k] = v;
            return _setHeader(k, v);
        };

        return xhr;
    }

    // Copy prototype so Frappe internals don't detect the swap
    PatchedXHR.prototype = OrigXHR.prototype;
    window.XMLHttpRequest = PatchedXHR;

    console.log('[PO Filter v8] XHR redirect installed');
}

























