function bartakke_update_items(frm) {
    if (frm.doc.docstatus !== 1) {
        return;
    }

    const child_docname = "items";

    const data = (frm.doc.items || []).map((d) => ({
        docname: d.name,
        name: d.name,
        item_code: d.item_code,
        item_name: d.item_name,
        customer_item_code: d.customer_item_code,
        custom_material: d.custom_material,
        custom_design: d.custom_design,
        delivery_date: d.delivery_date,
        qty: d.qty,
        rate: d.rate,
        uom: d.uom,
        conversion_factor: d.conversion_factor,
        item_tax_template: d.item_tax_template,
        custom_wo: d.custom_wo,
        billed_amt: d.billed_amt,
    }));

    const fields = [
        {
            fieldtype: "Data",
            fieldname: "docname",
            read_only: 1,
            hidden: 1,
        },
        {
            fieldtype: "Link",
            fieldname: "item_code",
            options: "Item",
            read_only: 1,
            hidden: 1,
            label: __("Item Code"),
        },
        {
            fieldtype: "Data",
            fieldname: "item_name",
            in_list_view: 1,
            reqd: 1,
            label: __("Item Name"),
            columns: 2,
        },
        {
            fieldtype: "Data",
            fieldname: "customer_item_code",
            in_list_view: 1,
            label: __("Customer Item Code"),
            columns: 1,
        },
        {
            fieldtype: "Link",
            fieldname: "custom_material",
            options: "Material",
            in_list_view: 1,
            label: __("Material"),
            columns: 1,
        },
        {
            fieldtype: "Link",
            fieldname: "custom_design",
            options: "Design",
            in_list_view: 1,
            label: __("Design"),
            columns: 1,
        },
        {
            fieldtype: "Data",
            fieldname: "custom_wo",
            in_list_view: 1,
            label: __("Work Order / WO"),
            columns: 2,
        },
        {
            fieldtype: "Float",
            fieldname: "qty",
            default: 0,
            in_list_view: 1,
            label: __("Qty"),
            columns: 1,
        },
        {
            fieldtype: "Currency",
            fieldname: "rate",
            options: "currency",
            default: 0,
            in_list_view: 1,
            label: __("Rate"),
            columns: 1,
        },
        {
            fieldtype: "Link",
            fieldname: "item_tax_template",
            options: "Item Tax Template",
            in_list_view: 1,
            label: __("Item Tax Template"),
            columns: 1,
        },
        {
            fieldtype: "Date",
            fieldname: "delivery_date",
            hidden: 1,
            label: __("Delivery Date"),
        },
        {
            fieldtype: "Link",
            fieldname: "uom",
            options: "UOM",
            hidden: 1,
            label: __("UOM"),
        },
        {
            fieldtype: "Float",
            fieldname: "conversion_factor",
            hidden: 1,
            label: __("Conversion Factor"),
        },
        {
            fieldtype: "Currency",
            fieldname: "billed_amt",
            options: "currency",
            read_only: 1,
            hidden: 1,
            label: __("Billed Amt"),
        },
    ];

    const dialog = new frappe.ui.Dialog({
        title: __("Update Items"),
        size: "extra-large",
        fields: [
            {
                fieldname: "trans_items",
                fieldtype: "Table",
                label: __("Items"),
                cannot_add_rows: false,
                in_place_edit: false,
                reqd: 1,
                data: data,
                get_data: () => data,
                fields: fields,
            },
        ],
        primary_action_label: __("Update"),
        primary_action() {
            const trans_items = (dialog.get_values().trans_items || []).filter(
                (item) => !!item.item_code || !!item.item_name
            );

            const find_existing = (row) => {
                if (!row.docname) return null;
                return (frm.doc.items || []).find((d) => d.name === row.docname) || null;
            };

            const standard_items = [];
            const billed_errors = [];

            trans_items.forEach((row) => {
                const existing = find_existing(row);
                const qty = flt(row.qty);
                const rate = flt(row.rate);
                const new_amt = flt(rate * qty);
                const billed = existing ? flt(existing.billed_amt) : 0;

                if (existing && billed > 0 && rate > 0 && billed > new_amt) {
                    billed_errors.push(
                        __(
                            "Row #{0}: Rate × Qty ({1}) cannot be less than Billed Amount ({2}) for Item {3}.",
                            [
                                existing.idx,
                                format_currency(new_amt, frm.doc.currency),
                                format_currency(billed, frm.doc.currency),
                                row.item_code || (existing && existing.item_code) || row.item_name,
                            ]
                        )
                    );
                    return;
                }

                const payload = {
                    item_code:
                        row.item_code ||
                        (existing && existing.item_code) ||
                        "Sales Item",
                    qty: qty,
                    rate: rate,
                    customer_item_code: row.customer_item_code,
                    delivery_date:
                        row.delivery_date ||
                        (existing && existing.delivery_date) ||
                        frm.doc.delivery_date,
                    uom: row.uom || (existing && existing.uom),
                    conversion_factor:
                        row.conversion_factor ||
                        (existing && existing.conversion_factor) ||
                        1,
                };

                if (row.docname) {
                    payload.docname = row.docname;
                }

                standard_items.push(payload);
            });

            if (billed_errors.length) {
                frappe.msgprint({
                    title: __("Cannot Update Items"),
                    indicator: "red",
                    message: billed_errors.join("<br>"),
                });
                return;
            }

            dialog.hide();

            frappe.call({
                method: "erpnext.controllers.accounts_controller.update_child_qty_rate",
                freeze: true,
                freeze_message: __("Updating Items..."),
                args: {
                    parent_doctype: "Sales Order",
                    trans_items: standard_items,
                    parent_doctype_name: frm.doc.name,
                    child_docname: child_docname,
                },
                callback() {
                    frm.reload_doc().then(() => {
                        // Build the list of rows that need CUSTOM fields updated
                        // (item_name / customer_item_code / custom_material /
                        // custom_design / custom_wo). These are NOT handled by
                        // update_child_qty_rate, so we push them directly via
                        // the generic, always-available frappe.client.set_value
                        // method.
                        const custom_field_updates = [];

                        trans_items.forEach((row) => {
                            let docname = row.docname;

                            // For newly added rows (no docname originally), find the
                            // freshly created child row after reload by matching
                            // item_code + qty + rate.
                            if (!docname) {
                                const match = (frm.doc.items || []).find(
                                    (d) =>
                                        d.item_code === (row.item_code || "Sales Item") &&
                                        flt(d.qty) === flt(row.qty) &&
                                        flt(d.rate) === flt(row.rate)
                                );
                                if (match) {
                                    docname = match.name;
                                }
                            }

                            if (!docname) return;

                            const field_values = {};

                            // FIX: item_name was missing here earlier, so Item Name
                            // edits made in the dialog were silently dropped and
                            // never persisted to the Sales Order Item row.
                            // update_child_qty_rate does not set item_name for
                            // existing rows (it's normally fetched via item_code),
                            // so it must go through set_value like the other
                            // custom fields.
                            if (row.item_name !== undefined) {
                                field_values.item_name = row.item_name;
                            }
                            if (row.customer_item_code !== undefined) {
                                field_values.customer_item_code = row.customer_item_code;
                            }
                            if (row.custom_material !== undefined) {
                                field_values.custom_material = row.custom_material;
                            }
                            if (row.custom_design !== undefined) {
                                field_values.custom_design = row.custom_design;
                            }
                            // FIX: custom_wo was missing here earlier, so Work Order
                            // edits made in the dialog were silently dropped and
                            // never persisted to the Sales Order Item row.
                            if (row.custom_wo !== undefined) {
                                field_values.custom_wo = row.custom_wo;
                            }
                            // FIX: item_tax_template was also missing here earlier,
                            // so Item Tax Template edits made in the dialog were
                            // silently dropped and never persisted to the Sales
                            // Order Item row. update_child_qty_rate does not set
                            // this field for existing rows either.
                            if (row.item_tax_template !== undefined) {
                                field_values.item_tax_template = row.item_tax_template;
                            }

                            if (Object.keys(field_values).length) {
                                custom_field_updates.push({
                                    docname: docname,
                                    field_values: field_values,
                                });
                            }
                        });

                        const run_custom_field_updates = () => {
                            if (!custom_field_updates.length) {
                                return Promise.resolve();
                            }

                            // IMPORTANT: run these ONE AT A TIME (not Promise.all).
                            // frappe.client.set_value on a child row (Sales Order Item)
                            // saves the whole parent Sales Order under the hood. Firing
                            // multiple calls in parallel races on the parent's
                            // "modified" timestamp and throws
                            // frappe.exceptions.TimestampMismatchError (417), silently
                            // failing every call after the first.
                            const run_one = (index) => {
                                if (index >= custom_field_updates.length) {
                                    return Promise.resolve();
                                }
                                const u = custom_field_updates[index];
                                return frappe
                                    .call({
                                        method: "frappe.client.set_value",
                                        args: {
                                            doctype: "Sales Order Item",
                                            name: u.docname,
                                            fieldname: u.field_values,
                                        },
                                    })
                                    .then(() => run_one(index + 1));
                            };

                            return run_one(0);
                        };

                        frappe.dom.freeze(__("Updating item details..."));

                        run_custom_field_updates()
                            .then(() => {
                                frappe.dom.unfreeze();
                                frm.reload_doc();
                            })
                            .catch((err) => {
                                frappe.dom.unfreeze();
                                console.error(err);
                                frappe.msgprint({
                                    title: __("Error"),
                                    indicator: "red",
                                    message: __(
                                        "Some custom fields (Item Name / Customer Item Code / Material / Design / WO / Item Tax Template) could not be updated. Please check the console for details."
                                    ),
                                });
                                frm.reload_doc();
                            });
                    });
                },
            });
        },
    });

    dialog.show();
}

frappe.ui.form.on("Sales Order", {
    refresh(frm) {
        if (frm.doc.docstatus === 1 && frm.doc.status !== "Closed") {
            frm.remove_custom_button(__("Update Items"));
            frm.add_custom_button(__("Update Items"), () => {
                bartakke_update_items(frm);
            });
        }
    },
});

