        const print_formats = [
            "Tax Invoice.",
            "Commercial Invoice",
            "Export Tax Invoice.",
            "GST Tax Invoice",
            "Packing Slip1",
            "Scrap Invoice",
            "Sale of Capital Goods"
        ];

